        pos+=1
        result |= (b & 0x7f) << shift
        if not (b & 0x80):
            break
        shift+=7
    return result, pos

def zigzag_to_int(n):
    return (n >> 1) ^ -(n & 1)

def read_zigzag_varint(buf,pos):
    v,pos=read_varint(buf,pos)
    return zigzag_to_int(v), pos

def decode_value(buf,pos,field_type,depth):
    indent="  "*depth
    if field_type==1:
