        return pos
    elif field_type==2:
        print(f"{indent} FALSE")
        return pos
    elif field_type==3:
        print(f"{indent} BYTE {buf[pos]}")
        return pos+1
    elif field_type in (4,5,6):
        v,pos2=read_zigzag_varint(buf,pos)
        print(f"{indent} INT {v}")
        return pos2
