        return pos
    elif field_type==12:
        return decode_struct(buf,pos,depth)
    else:
        print(f"{indent} UNKNOWN {field_type}")
        return pos

def decode_struct(buf,pos,depth=0):
    indent="  "*depth
    last_field_id=0
    while True:
        b=buf[pos]
        pos+=1
        ftype=b & 0x0f
        delta=(b>>4)&0x0f
        if ftype==0:
            break
        if delta==0:
