            pos=decode_struct(buf,pos,depth+1)
        elif ftype==9:
            pos=decode_value(buf,pos,9,depth+1)
        else:
            pos=decode_value(buf,pos,ftype,depth+1)
    print(f"{indent} END STRUCT")
    return pos

