subprocess.run(["tmux","kill-session","-t",session], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
subprocess.run(["tmux","new-session","-d","-x","60","-y","20","-s",session], check=True)
time.sleep(0.5)
subprocess.run(["tmux","send-keys","-t",session,"bash --noprofile --norc --noediting","Enter"], check=True)
time.sleep(0.5)
def send(k,w=0.6):
    subprocess.run(["tmux","send-keys","-t",session,k], check=True)
    time.sleep(w)
def cap():
    return subprocess.run(["tmux","capture-pane","-p","-t",session], capture_output=True, text=True).stdout
def cap_esc():
    return subprocess.run(["tmux","capture-pane","-p","-e","-t",session], capture_output=True, text=True).stdout
def clear():
    subprocess.run(["tmux","send-keys","-t",session,"clear","Enter"], check=True)
    time.sleep(0.3)
def parse_sel(esc):
    for line in esc.splitlines():
        if "60;60;60" in line:
            m=re.search(r'\[1;4m\x1b\[38;5;8m(\d+)', line)
            if m:
                return m.group(1)
    return None
def first_vis(plain):
    for line in plain.splitlines():
        if '│' in line:
            left=line.split('│')[0]
            m=re.match(r'\s*(\d+)', left)
            if m:
                return m.group(1)
    return None

clear()
subprocess.run(["tmux","send-keys","-t",session,"./executable assets/alltypes_tiny_pages.parquet","Enter"], check=True)
time.sleep(1.2)
# go down many times to mid
for _ in range(20):
    send("Down")
time.sleep(0.5)
for i in range(20):
    esc=cap_esc()
    plain=cap()
    sel=parse_sel(esc)
    fv=first_vis(plain)
    cnt=sum(1 for line in plain.splitlines() if '│' in line and re.match(r'\s*\d+', line.split('│')[0]))
    print(f"Up step {i}: sel={sel} first={fv} visible={cnt}")
    send("Up")

send("q")
subprocess.run(["tmux","kill-session","-t",session])
