// Thrift compact protocol decoder

#[derive(Debug)]
pub enum ThriftFieldType {
    Stop = 0,
    True = 1,
    False = 2,
    Byte = 3,
    I16 = 4,
    I32 = 5,
    I64 = 6,
    Double = 7,
    Binary = 8,
    List = 9,
    Set = 10,
    Map = 11,
    Struct = 12,
}

impl From<u8> for ThriftFieldType {
    fn from(v: u8) -> Self {
        match v {
            0 => ThriftFieldType::Stop,
            1 => ThriftFieldType::True,
            2 => ThriftFieldType::False,
            3 => ThriftFieldType::Byte,
            4 => ThriftFieldType::I16,
            5 => ThriftFieldType::I32,
            6 => ThriftFieldType::I64,
            7 => ThriftFieldType::Double,
            8 => ThriftFieldType::Binary,
            9 => ThriftFieldType::List,
            10 => ThriftFieldType::Set,
            11 => ThriftFieldType::Map,
            12 => ThriftFieldType::Struct,
            _ => ThriftFieldType::Stop,
        }
    }
}

pub fn read_varint(buf: &[u8], mut pos: usize) -> (u64, usize) {
    let mut result: u64 = 0;
    let mut shift = 0;
    loop {
        let b = buf[pos];
        pos += 1;
        result |= ((b & 0x7f) as u64) << shift;
        if (b & 0x80) == 0 {
            break;
        }
        shift += 7;
    }
    (result, pos)
}

pub fn zigzag_to_i64(n: u64) -> i64 {
    ((n >> 1) as i64) ^ -((n & 1) as i64)
}

pub fn read_zigzag_varint(buf: &[u8], pos: usize) -> (i64, usize) {
    let (v, new_pos) = read_varint(buf, pos);
    (zigzag_to_i64(v), new_pos)
}

pub fn read_zigzag_i32(buf: &[u8], pos: usize) -> (i32, usize) {
    let (v, p) = read_zigzag_varint(buf, pos);
    (v as i32, p)
}
pub fn read_zigzag_i64(buf: &[u8], pos: usize) -> (i64, usize) {
    read_zigzag_varint(buf, pos)
}

pub fn skip_struct(buf: &[u8], mut pos: usize) -> usize {
    let mut last_field_id: i64 = 0;
    loop {
        if pos >= buf.len() {
            break;
        }
        let b = buf[pos];
        pos += 1;
        let ftype = (b & 0x0f) as u8;
        let delta = ((b >> 4) & 0x0f) as u8;
        if ftype == 0 {
            break;
        }
        if delta == 0 {
            let (fid, new_pos) = read_varint(buf, pos);
            pos = new_pos;
            last_field_id = fid as i64;
        } else {
            last_field_id += delta as i64;
        }
        match ftype {
            1 | 2 => {},
            3 => { pos += 1; },
            4 | 5 | 6 => {
                let (_, new_pos) = read_zigzag_varint(buf, pos);
                pos = new_pos;
            },
            7 => { pos += 8; },
            8 => {
                let (len, new_pos) = read_varint(buf, pos);
                pos = new_pos + len as usize;
            },
            9 | 10 => {
