pub fn read_varint(buf: &[u8], mut pos: usize) -> (u64, usize) {
    let mut result: u64 = 0;
    let mut shift = 0;
    loop {
        let b = buf[pos];
        pos += 1;
        result |= ((b & 0x7f) as u64) << shift;
        if (b & 0x80) == 0 {
            break;
        }
        shift += 7;
    }
    (result, pos)
}

pub fn zigzag_to_i64(n: u64) -> i64 {
    ((n >> 1) as i64) ^ -((n & 1) as i64)
}

pub fn read_zigzag_varint(buf: &[u8], pos: usize) -> (i64, usize) {
    let (v, new_pos) = read_varint(buf, pos);
    (zigzag_to_i64(v), new_pos)
}

pub fn read_zigzag_i32(buf: &[u8], pos: usize) -> (i32, usize) {
    let (v, p) = read_zigzag_varint(buf, pos);
    (v as i32, p)
}
pub fn read_zigzag_i64(buf: &[u8], pos: usize) -> (i64, usize) {
    read_zigzag_varint(buf, pos)
}

pub fn skip_struct(buf: &[u8], mut pos: usize) -> usize {
    let mut last_field_id: i64 = 0;
    loop {
        if pos >= buf.len() {
            break;
        }
        let b = buf[pos];
        pos += 1;
        let ftype = (b & 0x0f) as u8;
        let delta = ((b >> 4) & 0x0f) as u8;
        if ftype == 0 {
            break;
        }
        if delta == 0 {
            let (fid, new_pos) = read_varint(buf, pos);
            pos = new_pos;
            last_field_id = fid as i64;
        } else {
            last_field_id += delta as i64;
        }
        match ftype {
            1 | 2 => {},
            3 => { pos += 1; },
            4 | 5 | 6 => {
                let (_, new_pos) = read_zigzag_varint(buf, pos);
                pos = new_pos;
            },
            7 => { pos += 8; },
            8 => {
                let (len, new_pos) = read_varint(buf, pos);
                pos = new_pos + len as usize;
            },
            9 | 10 => {
                let b2 = buf[pos];
                pos += 1;
                let elem_type = b2 & 0x0f;
                let size_nibble = (b2 >> 4) & 0x0f;
                let size = if size_nibble == 15 {
                    let (s, new_pos) = read_varint(buf, pos);
                    pos = new_pos;
                    s as usize
                } else {
                    size_nibble as usize
                };
                for _ in 0..size {
                    match elem_type {
                        12 => { pos = skip_struct(buf, pos); },
                        4 | 5 | 6 => {
                            let (_, new_pos) = read_zigzag_varint(buf, pos);
                            pos = new_pos;
                        },
                        8 => {
                            let (ll, new_pos) = read_varint(buf, pos);
                            pos = new_pos + ll as usize;
                        },
                        3 => { pos += 1; },
                        1 | 2 => {},
                        _ => { break; },
                    }
                }
            },
            11 => {
                // map: not used in parquet? skip
                // map header: key type, value type, size
                let b2 = buf[pos];
                pos += 1;
                let _key_type = b2 & 0x0f;
                let _val_type = (b2 >> 4) & 0x0f;
                // size as varint if needed? Actually map size is varint
                let (size, new_pos) = read_varint(buf, pos);
                pos = new_pos;
                for _ in 0..size {
                    // skip key and value - assume binary or int?
                    // For simplicity, skip as struct
                    pos = skip_struct(buf, pos);
                }
            },
            12 => {
                pos = skip_struct(buf, pos);
            },
            _ => { break; },
        }
    }
    pos
}
