}

// RLE / Bit-packed hybrid decoder for levels and dictionary indices

pub struct RleDecoder {
    data: Vec<u8>,
    pos: usize,
    bit_width: u8,
    // state for current run
    current_run_len: usize,
    current_run_pos: usize,
    current_value: i64,
    // for bit-packed
    bit_packed_count: usize,
    bit_packed_pos: usize,
    bit_buffer: u64,
    bits_in_buffer: usize,
}

impl RleDecoder {
    pub fn new(data: Vec<u8>, bit_width: u8) -> Self {
        Self {
            data,
            pos: 0,
            bit_width,
            current_run_len: 0,
            current_run_pos: 0,
            current_value: 0,
            bit_packed_count: 0,
            bit_packed_pos: 0,
            bit_buffer: 0,
            bits_in_buffer: 0,
        }
    }

    fn read_varint(&mut self) -> Option<u64> {
        if self.pos >= self.data.len() {
            return None;
        }
        let mut result: u64 = 0;
        let mut shift = 0;
        while self.pos < self.data.len() {
            let b = self.data[self.pos];
            self.pos += 1;
            result |= ((b & 0x7f) as u64) << shift;
            if (b & 0x80) == 0 {
                break;
            }
            shift += 7;
        }
        Some(result)
    }

    fn read_byte(&mut self) -> Option<u8> {
        if self.pos >= self.data.len() {
            None
        } else {
            let b = self.data[self.pos];
            self.pos += 1;
            Some(b)
        }
    }

    // For levels decoding, we decode according to hybrid RLE spec
    pub fn next(&mut self) -> Option<i64> {
        // If we are in a run
        if self.current_run_pos < self.current_run_len {
            self.current_run_pos += 1;
            return Some(self.current_value);
        }
        if self.bit_packed_pos < self.bit_packed_count {
            // decode bit-packed value
            // Need to ensure we have enough bits in buffer
            while self.bits_in_buffer < self.bit_width as usize {
                if self.pos >= self.data.len() {
                    // need more data but we are in bit-packed group of 8 values padded to bytes
                    break;
                }
                let b = self.data[self.pos] as u64;
                self.pos += 1;
                self.bit_buffer |= b << self.bits_in_buffer;
                self.bits_in_buffer += 8;
            }
            if self.bits_in_buffer < self.bit_width as usize {
                return None;
            }
            let mask = if self.bit_width == 0 { 0 } else { (1u64 << self.bit_width) - 1 };
            let val = self.bit_buffer & mask;
            self.bit_buffer >>= self.bit_width;
            self.bits_in_buffer -= self.bit_width as usize;
            self.bit_packed_pos += 1;
            return Some(val as i64);
        }

        // Read next run header
        let header = self.read_varint()?;
        if header & 1 == 0 {
            // RLE
            let run_len = (header >> 1) as usize;
            // Next, read value with bit_width bits? Actually for levels, value is encoded with bit_width? Or as varint?
            // For levels, after header, the value is encoded as little-endian with bit_width? Wait levels RLE: value is encoded as i32 with bit_width? Actually for RLE, the repeated value is stored as a single value? Let's check spec: RLE run: header (run_len <<1), then value (as per bit_width? Actually for levels, value is encoded as i32? Need to check)
            // For simplicity, assume bit_width bytes? But for definition levels, value is small and stored as 1 byte? In our earlier example, RLE run of 8 with value 1 was encoded as header 0x10 (16) then value 0x01 (1 byte). So value is 1 byte.
            // For general bit_width, value may be ceil(bit_width/8) bytes little endian?
            // We'll read ceil(bit_width/8) bytes.

            let bytes_needed = ((self.bit_width as usize + 7) / 8).max(1);
            let mut val_bytes = vec![0u8; bytes_needed];
            for i in 0..bytes_needed {
                val_bytes[i] = self.read_byte()?;
            }
            // Decode little endian
            let mut v = 0i64;
            for (i, &b) in val_bytes.iter().enumerate() {
                v |= (b as i64) << (8*i);
            }
            self.current_value = v;
            self.current_run_len = run_len;
            self.current_run_pos = 1;
            Some(v)
        } else {
            // Bit-packed: num_groups = header>>1
            let num_groups = (header >> 1) as usize;
            let num_values = num_groups * 8;
            self.bit_packed_count = num_values;
            self.bit_packed_pos = 0;
            self.bit_buffer = 0;
            self.bits_in_buffer = 0;
            // Now decode first value in this group on next iteration
            // We need to ensure we decode first value now
            // Recursively call next to get first bit-packed value
            self.next()
        }
    }
}

// Plain decoding for various physical types

pub fn decode_plain_int32(data: &[u8]) -> Vec<i32> {
    let mut vals = Vec::new();
    let mut pos = 0;
    while pos + 4 <= data.len() {
        let v = i32::from_le_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]);
        vals.push(v);
        pos += 4;
    }
    vals
}

pub fn decode_plain_int64(data: &[u8]) -> Vec<i64> {
    let mut vals = Vec::new();
    let mut pos = 0;
    while pos + 8 <= data.len() {
        let v = i64::from_le_bytes([
            data[pos], data[pos+1], data[pos+2], data[pos+3],
            data[pos+4], data[pos+5], data[pos+6], data[pos+7],
        ]);
        vals.push(v);
        pos += 8;
    }
    vals
}

pub fn decode_plain_float(data: &[u8]) -> Vec<f32> {
    let mut vals = Vec::new();
    let mut pos = 0;
    while pos + 4 <= data.len() {
        let v = f32::from_le_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]);
        vals.push(v);
