}

pub fn decode_plain_double(data: &[u8]) -> Vec<f64> {
    let mut vals = Vec::new();
    let mut pos = 0;
    while pos + 8 <= data.len() {
        let v = f64::from_le_bytes([
            data[pos], data[pos+1], data[pos+2], data[pos+3],
            data[pos+4], data[pos+5], data[pos+6], data[pos+7],
        ]);
        vals.push(v);
        pos += 8;
    }
    vals
}

pub fn decode_plain_byte_array(data: &[u8]) -> Vec<Vec<u8>> {
    let mut vals = Vec::new();
    let mut pos = 0;
    while pos + 4 <= data.len() {
        let len = u32::from_le_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]) as usize;
        pos += 4;
        if pos + len > data.len() {
            break;
        }
        vals.push(data[pos..pos+len].to_vec());
        pos += len;
    }
    vals
}

// Bit-packed decoder for dictionary indices

pub fn decode_bitpacked(data: &[u8], bit_width: u8, num_values: usize) -> Vec<i32> {
    // The data is encoded as: [bit_width byte][RLE/BP data]
    // But we already have bit_width separate? For dictionary indices, data starts with bit_width, then hybrid RLE.
    // This function expects hybrid RLE data after bit_width byte.
    // Let's implement hybrid decoder similar to levels but returning indices.

    let mut decoder = RleDecoder::new(data.to_vec(), bit_width);
    let mut out = Vec::with_capacity(num_values);
    for _ in 0..num_values {
        if let Some(v) = decoder.next() {
            out.push(v as i32);
        } else {
            break;
        }
    }
    out
}

