pub fn parse_file_metadata(buf: &[u8]) -> Result<FileMetaData, String> {
    let mut pos = 0;
    let mut last_field_id: i64 = 0;
    let mut version: i32 = 0;
    let mut schema: Vec<SchemaElement> = Vec::new();
    let mut num_rows: i64 = 0;
    let mut row_groups: Vec<RowGroup> = Vec::new();
    let mut created_by: Option<String> = None;
    let mut kv_metadata: Vec<KeyValue> = Vec::new();

    while pos < buf.len() {
        let b = buf[pos];
        pos += 1;
        let ftype = b & 0x0f;
        let delta = (b >> 4) & 0x0f;
        if ftype == 0 {
            break;
        }
        if delta == 0 {
            let (fid, new_pos) = read_varint(buf, pos);
            pos = new_pos;
            last_field_id = fid as i64;
        } else {
            last_field_id += delta as i64;
        }

        match last_field_id {
            1 => {
                // version i32
                let (v, new_pos) = crate::thrift::read_zigzag_i32(buf, pos);
                pos = new_pos;
                version = v;
            },
            2 => {
                // schema list<SchemaElement>
                let b2 = buf[pos];
                pos += 1;
                let elem_type = b2 & 0x0f;
                let size_nibble = (b2 >> 4) & 0x0f;
                let size = if size_nibble == 15 {
                    let (s, new_pos) = read_varint(buf, pos);
                    pos = new_pos;
                    s as usize
                } else {
                    size_nibble as usize
                };
                if elem_type != 12 {
                    return Err("schema list elem type not struct".to_string());
                }
                for _ in 0..size {
                    let (se, new_pos) = parse_schema_element(buf, pos)?;
                    pos = new_pos;
                    schema.push(se);
                }
            },
            3 => {
                let (v, new_pos) = crate::thrift::read_zigzag_i64(buf, pos);
                pos = new_pos;
                num_rows = v;
            },
            4 => {
                // row_groups list
                let b2 = buf[pos];
                pos += 1;
                let elem_type = b2 & 0x0f;
                let size_nibble = (b2 >> 4) & 0x0f;
                let size = if size_nibble == 15 {
                    let (s, new_pos) = read_varint(buf, pos);
                    pos = new_pos;
                    s as usize
                } else {
                    size_nibble as usize
                };
                if elem_type != 12 {
                    return Err("row_groups elem type not struct".to_string());
                }
                for _ in 0..size {
                    let (rg, new_pos) = parse_row_group(buf, pos)?;
                    pos = new_pos;
                    row_groups.push(rg);
                }
            },
            5 => {
                // key_value_metadata list<KeyValue>
                let b2 = buf[pos];
                pos += 1;
                let _elem_type = b2 & 0x0f;
                let size_nibble = (b2 >> 4) & 0x0f;
                let size = if size_nibble == 15 {
                    let (s, new_pos) = read_varint(buf, pos);
                    pos = new_pos;
                    s as usize
                } else {
                    size_nibble as usize
                };
                for _ in 0..size {
                    let (kv, new_pos) = parse_key_value(buf, pos)?;
                    pos = new_pos;
                    kv_metadata.push(kv);
                }
            },
            6 => {
                // created_by binary
                let (len, new_pos) = read_varint(buf, pos);
                pos = new_pos;
                if pos + len as usize > buf.len() {
                    return Err("created_by length overflow".to_string());
                }
                let s = String::from_utf8_lossy(&buf[pos..pos+len as usize]).to_string();
                pos += len as usize;
                created_by = Some(s);
            },
            _ => {
                // skip unknown
                pos = skip_field(buf, pos, ftype)?;
            }
        }
    }

    Ok(FileMetaData {
        version,
        schema,
        num_rows,
        row_groups,
        created_by,
        key_value_metadata: kv_metadata,
    })
}

fn skip_field(buf: &[u8], mut pos: usize, ftype: u8) -> Result<usize, String> {
    match ftype {
        1 | 2 => Ok(pos), // bool true/false no extra data
        3 => {
            if pos >= buf.len() { return Err("skip byte overflow".to_string()); }
            Ok(pos+1)
        },
        4 | 5 | 6 => {
            let (_, new_pos) = read_zigzag_varint(buf, pos);
            Ok(new_pos)
        },
        7 => Ok(pos+8),
        8 => {
            let (len, new_pos) = read_varint(buf, pos);
            pos = new_pos;
            if pos + len as usize > buf.len() {
                return Err("skip binary overflow".to_string());
            }
            Ok(pos + len as usize)
        },
        9 | 10 => {
            if pos >= buf.len() { return Err("skip list no header".to_string()); }
            let b2 = buf[pos];
            pos += 1;
            let elem_type = b2 & 0x0f;
            let size_nibble = (b2 >> 4) & 0x0f;
            let size = if size_nibble == 15 {
                let (s, new_pos) = read_varint(buf, pos);
                pos = new_pos;
                s as usize
            } else {
                size_nibble as usize
            };
            for _ in 0..size {
                match elem_type {
                    12 => { pos = skip_struct(buf, pos); },
                    4 | 5 | 6 => {
                        let (_, new_pos) = read_zigzag_varint(buf, pos);
                        pos = new_pos;
                    },
                    8 => {
                        let (ll, new_pos) = read_varint(buf, pos);
                        pos = new_pos + ll as usize;
                    },
                    3 => { pos += 1; },
                    1 | 2 => {},
                    7 => { pos += 8; },
                    _ => { break; },
                }
            }
            Ok(pos)
        },
        11 => {
            // map: not fully implemented
            // map header includes key type, value type, size
            if pos >= buf.len() { return Err("skip map no header".to_string()); }
            let _b2 = buf[pos];
            pos += 1;
            let (size, new_pos) = read_varint(buf, pos);
            pos = new_pos;
            for _ in 0..size {
                // skip key and value as generic fields? For parquet, map not used in top fields
                // We'll attempt to skip as if both are struct/binary
                pos = skip_struct(buf, pos);
            }
            Ok(pos)
        },
        12 => Ok(skip_struct(buf, pos)),
        _ => Err(format!("unknown field type {}", ftype)),
    }
}

fn parse_schema_element(buf: &[u8], pos: usize) -> Result<(SchemaElement, usize), String> {
    let mut p = pos;
    let mut last_id: i64 = 0;
    let mut name = String::new();
    let mut typ: Option<i32> = None;
    let mut repetition: Option<i32> = None;
    let mut num_children: Option<i32> = None;

    loop {
        if p >= buf.len() { return Err("schema element overflow".to_string()); }
        let b = buf[p];
        p += 1;
        let ftype = b & 0x0f;
        let delta = (b >> 4) & 0x0f;
        if ftype == 0 { break; }
        if delta == 0 {
            let (fid, new_pos) = read_varint(buf, p);
            p = new_pos;
            last_id = fid as i64;
        } else {
            last_id += delta as i64;
        }
        match last_id {
            1 => {
                if ftype == 5 || ftype == 4 {
                    let (v, new_pos) = crate::thrift::read_zigzag_i32(buf, p);
                    p = new_pos;
                    typ = Some(v);
                } else {
                    p = skip_field(buf, p, ftype)?;
                }
            },
            2 => {
                // type_length? Not needed
                p = skip_field(buf, p, ftype)?;
            },
            3 => {
                if ftype == 5 || ftype == 4 {
                    let (v, new_pos) = crate::thrift::read_zigzag_i32(buf, p);
                    p = new_pos;
                    repetition = Some(v);
                } else {
                    p = skip_field(buf, p, ftype)?;
                }
            },
            4 => {
                if ftype == 8 {
                    let (len, new_pos) = read_varint(buf, p);
                    p = new_pos;
                    if p + len as usize > buf.len() { return Err("schema name overflow".to_string()); }
                    name = String::from_utf8_lossy(&buf[p..p+len as usize]).to_string();
                    p += len as usize;
                } else {
                    p = skip_field(buf, p, ftype)?;
                }
            },
            5 => {
                if ftype == 5 || ftype == 4 {
                    let (v, new_pos) = crate::thrift::read_zigzag_i32(buf, p);
                    p = new_pos;
                    num_children = Some(v);
                } else {
                    p = skip_field(buf, p, ftype)?;
                }
            },
            _ => {
                p = skip_field(buf, p, ftype)?;
            }
        }
    }

    Ok((SchemaElement { name, r#type: typ, repetition, num_children, logical_type: None, converted_type: None }, p))
}

fn parse_key_value(buf: &[u8], pos: usize) -> Result<(KeyValue, usize), String> {
    let mut p = pos;
    let mut last_id: i64 = 0;
    let mut key = String::new();
    let mut value: Option<String> = None;
    loop {
        if p >= buf.len() { return Err("kv overflow".to_string()); }
        let b = buf[p];
        p += 1;
        let ftype = b & 0x0f;
        let delta = (b >> 4) & 0x0f;
        if ftype == 0 { break; }
        if delta == 0 {
            let (fid, new_pos) = read_varint(buf, p);
            p = new_pos;
            last_id = fid as i64;
        } else {
            last_id += delta as i64;
        }
        if last_id == 1 && ftype == 8 {
            let (len, new_pos) = read_varint(buf, p);
            p = new_pos;
            key = String::from_utf8_lossy(&buf[p..p+len as usize]).to_string();
            p += len as usize;
        } else if last_id == 2 && ftype == 8 {
            let (len, new_pos) = read_varint(buf, p);
            p = new_pos;
            let v = String::from_utf8_lossy(&buf[p..p+len as usize]).to_string();
            p += len as usize;
            value = Some(v);
        } else {
            p = skip_field(buf, p, ftype)?;
        }
    }
    Ok((KeyValue { key, value }, p))
}

fn parse_row_group(buf: &[u8], pos: usize) -> Result<(RowGroup, usize), String> {
    let mut p = pos;
    let mut last_id: i64 = 0;
    let mut columns: Vec<ColumnChunk> = Vec::new();
    let mut total_byte_size: i64 = 0;
    let mut num_rows: i64 = 0;

    loop {
        if p >= buf.len() { return Err("row group overflow".to_string()); }
        let b = buf[p];
        p += 1;
        let ftype = b & 0x0f;
        let delta = (b >> 4) & 0x0f;
        if ftype == 0 { break; }
        if delta == 0 {
            let (fid, new_pos) = read_varint(buf, p);
            p = new_pos;
            last_id = fid as i64;
        } else {
            last_id += delta as i64;
        }
        match last_id {
            1 => {
                // columns list
                if ftype != 9 { p = skip_field(buf, p, ftype)?; continue; }
                let b2 = buf[p];
                p += 1;
                let elem_type = b2 & 0x0f;
                let size_nibble = (b2 >> 4) & 0x0f;
                let size = if size_nibble == 15 {
                    let (s, new_pos) = read_varint(buf, p);
                    p = new_pos;
                    s as usize
                } else {
                    size_nibble as usize
                };
                if elem_type != 12 {
                    return Err("row group columns not struct".to_string());
                }
                for _ in 0..size {
                    let (col, new_pos) = parse_column_chunk(buf, p)?;
                    p = new_pos;
                    columns.push(col);
                }
            },
            2 => {
                let (v, new_pos) = crate::thrift::read_zigzag_i64(buf, p);
                p = new_pos;
                total_byte_size = v;
            },
            3 => {
                let (v, new_pos) = crate::thrift::read_zigzag_i64(buf, p);
                p = new_pos;
                num_rows = v;
            },
            _ => {
                p = skip_field(buf, p, ftype)?;
            }
        }
    }

    Ok((RowGroup { columns, total_byte_size, num_rows }, p))
}

fn parse_column_chunk(buf: &[u8], pos: usize) -> Result<(ColumnChunk, usize), String> {
    let mut p = pos;
    let mut last_id: i64 = 0;
    let mut file_offset: i64 = 0;
    let mut meta: Option<ColumnMetaData> = None;

    loop {
        if p >= buf.len() { return Err("column chunk overflow".to_string()); }
        let b = buf[p];
        p += 1;
        let ftype = b & 0x0f;
        let delta = (b >> 4) & 0x0f;
        if ftype == 0 { break; }
        if delta == 0 {
            let (fid, new_pos) = read_varint(buf, p);
            p = new_pos;
            last_id = fid as i64;
        } else {
            last_id += delta as i64;
        }
        match last_id {
            2 => {
                let (v, new_pos) = crate::thrift::read_zigzag_i64(buf, p);
                p = new_pos;
                file_offset = v;
            },
            3 => {
                if ftype != 12 {
                    p = skip_field(buf, p, ftype)?;
                    continue;
                }
                let (cm, new_pos) = parse_column_metadata(buf, p)?;
                p = new_pos;
                meta = Some(cm);
            },
            _ => {
                p = skip_field(buf, p, ftype)?;
            }
        }
    }

    let meta = meta.ok_or("column chunk missing meta".to_string())?;
    Ok((ColumnChunk { file_offset, meta_data: meta }, p))
}

fn parse_column_metadata(buf: &[u8], pos: usize) -> Result<(ColumnMetaData, usize), String> {
    let mut p = pos;
    let mut last_id: i64 = 0;
    let mut typ: i32 = 0;
    let mut encodings: Vec<i32> = Vec::new();
    let mut path_in_schema: Vec<String> = Vec::new();
    let mut codec: i32 = 0;
    let mut num_values: i64 = 0;
    let mut total_uncompressed: i64 = 0;
    let mut total_compressed: i64 = 0;
    let mut data_page_offset: i64 = 0;
    let mut dict_page_offset: Option<i64> = None;
    let mut statistics: Option<Statistics> = None;

    loop {
        if p >= buf.len() { return Err("col meta overflow".to_string()); }
        let b = buf[p];
        p += 1;
        let ftype = b & 0x0f;
        let delta = (b >> 4) & 0x0f;
        if ftype == 0 { break; }
        if delta == 0 {
            let (fid, new_pos) = read_varint(buf, p);
            p = new_pos;
            last_id = fid as i64;
        } else {
            last_id += delta as i64;
        }
        match last_id {
            1 => {
                let (v, new_pos) = crate::thrift::read_zigzag_i32(buf, p);
                p = new_pos;
                typ = v;
            },
            2 => {
                // encodings list<i32>
                if ftype != 9 { p = skip_field(buf, p, ftype)?; continue; }
                let b2 = buf[p];
                p += 1;
                let elem_type = b2 & 0x0f;
                let size_nibble = (b2 >> 4) & 0x0f;
                let size = if size_nibble == 15 {
                    let (s, new_pos) = read_varint(buf, p);
                    p = new_pos;
                    s as usize
                } else {
                    size_nibble as usize
                };
                if elem_type != 5 {
                    // skip
                    for _ in 0..size { let (_, np) = crate::thrift::read_zigzag_i32(buf, p); p = np; }
                } else {
                    for _ in 0..size {
                        let (v, np) = crate::thrift::read_zigzag_i32(buf, p);
                        p = np;
                        encodings.push(v);
                    }
                }
            },
            3 => {
                // path_in_schema list<string>
                if ftype != 9 { p = skip_field(buf, p, ftype)?; continue; }
                let b2 = buf[p];
                p += 1;
                let elem_type = b2 & 0x0f;
                let size_nibble = (b2 >> 4) & 0x0f;
                let size = if size_nibble == 15 {
                    let (s, new_pos) = read_varint(buf, p);
                    p = new_pos;
                    s as usize
                } else {
                    size_nibble as usize
                };
                if elem_type != 8 {
                    for _ in 0..size { p = skip_field(buf, p, elem_type)?; }
                } else {
                    for _ in 0..size {
                        let (len, np) = read_varint(buf, p);
                        p = np;
                        let s = String::from_utf8_lossy(&buf[p..p+len as usize]).to_string();
                        p += len as usize;
                        path_in_schema.push(s);
                    }
                }
            },
            4 => {
                let (v, np) = crate::thrift::read_zigzag_i32(buf, p);
                p = np;
                codec = v;
            },
            5 => {
                let (v, np) = crate::thrift::read_zigzag_i64(buf, p);
                p = np;
                num_values = v;
            },
            6 => {
                let (v, np) = crate::thrift::read_zigzag_i64(buf, p);
                p = np;
                total_uncompressed = v;
            },
            7 => {
                let (v, np) = crate::thrift::read_zigzag_i64(buf, p);
                p = np;
                total_compressed = v;
            },
            9 => {
                let (v, np) = crate::thrift::read_zigzag_i64(buf, p);
                p = np;
                data_page_offset = v;
            },
            11 => {
                let (v, np) = crate::thrift::read_zigzag_i64(buf, p);
                p = np;
                dict_page_offset = Some(v);
            },
            12 => {
                // statistics
                if ftype == 12 {
                    let (st, np) = parse_statistics(buf, p)?;
                    p = np;
                    statistics = Some(st);
                } else {
                    p = skip_field(buf, p, ftype)?;
                }
            },
            _ => {
                p = skip_field(buf, p, ftype)?;
            }
        }
    }

    Ok((ColumnMetaData {
        r#type: typ,
        encodings,
        path_in_schema,
        codec,
        num_values,
        total_uncompressed_size: total_uncompressed,
        total_compressed_size: total_compressed,
        data_page_offset,
        dictionary_page_offset: dict_page_offset,
        statistics,
    }, p))
}

fn parse_statistics(buf: &[u8], pos: usize) -> Result<(Statistics, usize), String> {
    let mut p = pos;
    let mut last_id: i64 = 0;
    let mut min: Option<Vec<u8>> = None;
    let mut max: Option<Vec<u8>> = None;
    let mut null_count: Option<i64> = None;
