fn jd_to_date(jd: i64) -> (i32, u32, u32) {
    // Convert Julian day to Gregorian date using algorithm
    // From https://en.wikipedia.org/wiki/Julian_day
    let mut l = jd + 68569;
    let n = (4 * l) / 146097;
    l = l - (146097 * n + 3) / 4;
    let i = (4000 * (l + 1)) / 1461001;
    l = l - (1461 * i) / 4 + 31;
    let j = (80 * l) / 2447;
    let day = l - (2447 * j) / 80;
    l = j / 11;
    let month = j + 2 - 12 * l;
    let year = 100 * (n - 49) + i + l;
    (year as i32, month as u32, day as u32)
}

