pub fn run(file: ParquetFile) -> io::Result<()> {
    // Setup terminal
    ratatui::init();
    let result = run_app(file);
    ratatui::restore();
    result
}

fn run_app(file: ParquetFile) -> io::Result<()> {
    // Build flat lists
    let schema_flat = flatten_schema_tree(&file.schema_tree);
    let schema_state = SchemaState {
        selected: 0,
        scroll: 0,
        flat_nodes: schema_flat.clone(),
    };
    let rg_state = RowGroupState {
        rg_selected: 0,
        schema_selected: 0,
        flat_nodes: schema_flat,
    };

    let mut app = App {
        file,
        tab: Tab::Visualize,
        visualize: VisualizeState { row_selected: 0, row_offset: 0, col_offset: 0 },
        schema: schema_state,
        row_groups: rg_state,
        terminal_height: 0,
    };

    loop {
        ratatui::DefaultTerminal::new()?.draw(|f| {
            app.terminal_height = f.area().height as usize;
            draw(f, &mut app);
        })?;

        // Handle events
        if event::poll(Duration::from_millis(200))? {
            if let Event::Key(k) = event::read()? {
                match k.code {
                    KeyCode::Char('q') | KeyCode::Char('Q') => break,
                    KeyCode::Tab => {
                        let next = (app.tab as usize + 1) % 4;
                        app.tab = Tab::from_usize(next);
                    },
                    KeyCode::BackTab => {
                        let prev = (app.tab as usize + 3) % 4;
                        app.tab = Tab::from_usize(prev);
                    },
                    KeyCode::Down => {
                        match app.tab {
                            Tab::Visualize => {
                                let num_rows = app.file.columns_data.first().map(|c| c.values.len()).unwrap_or(0);
                                if app.visualize.row_selected + 1 < num_rows {
                                    app.visualize.row_selected += 1;
                                    // Adjust offset
                                    let visible = get_visualize_visible_rows(app.terminal_height);
                                    if app.visualize.row_selected >= app.visualize.row_offset + visible - 1 {
                                        // move offset by 1? Actually original moves offset by 1 when reaching bottom
                                        app.visualize.row_offset = app.visualize.row_selected - visible + 2;
                                        if app.visualize.row_offset > num_rows {
                                            app.visualize.row_offset = num_rows.saturating_sub(visible);
                                        }
                                    }
                                }
                            },
                            Tab::Schema => {
                                if app.schema.selected + 1 < app.schema.flat_nodes.len() {
                                    app.schema.selected += 1;
                                }
                            },
                            Tab::RowGroups => {
                                if app.row_groups.schema_selected + 1 < app.row_groups.flat_nodes.len() {
                                    app.row_groups.schema_selected += 1;
                                }
                            },
                            Tab::Metadata => {},
                        }
                    },
                    KeyCode::Up => {
                        match app.tab {
                            Tab::Visualize => {
                                if app.visualize.row_selected > 0 {
                                    app.visualize.row_selected -= 1;
                                    if app.visualize.row_selected < app.visualize.row_offset {
                                        app.visualize.row_offset = app.visualize.row_selected;
                                    }
                                }
                            },
                            Tab::Schema => {
                                if app.schema.selected > 0 {
                                    app.schema.selected -= 1;
                                }
                            },
                            Tab::RowGroups => {
                                if app.row_groups.schema_selected > 0 {
                                    app.row_groups.schema_selected -= 1;
                                }
                            },
                            Tab::Metadata => {},
                        }
                    },
                    KeyCode::Right => {
                        match app.tab {
                            Tab::Visualize => {
                                let num_cols = app.file.columns_data.len();
                                if app.visualize.col_offset + 1 < num_cols {
                                    app.visualize.col_offset += 1;
                                }
                            },
                            Tab::Schema => {
                                app.schema.scroll += 1;
                            },
                            Tab::RowGroups => {
                                // Iterate row groups
                                let num_rgs = app.file.metadata.row_groups.len();
                                if num_rgs > 0 {
                                    app.row_groups.rg_selected = (app.row_groups.rg_selected + 1) % num_rgs;
                                }
                            },
                            _ => {},
                        }
                    },
                    KeyCode::Left => {
                        match app.tab {
                            Tab::Visualize => {
                                if app.visualize.col_offset > 0 {
                                    app.visualize.col_offset -= 1;
                                }
                            },
                            Tab::Schema => {
