                    },
                    KeyCode::Char('d') | KeyCode::Char('D') => {
                        if app.tab == Tab::Visualize {
                            // Page down: move selection by visible -1, offset logic
                            let visible = get_visualize_visible_rows(app.terminal_height);
                            let num_rows = app.file.columns_data.first().map(|c| c.values.len()).unwrap_or(0);
                            let new_sel = std::cmp::min(num_rows.saturating_sub(1), app.visualize.row_selected + visible - 1);
                            // According to observed: first page down offset moves by 1? But our derived offset formula for page down is sel - visible +2
                            // Let's follow observed pattern: after page down, offset = sel - visible +2, but first time offset+1?
                            // Actually our earlier observation for page down: offset = sel - visible +2, sel += visible -1
                            // Let's use that
                            let old_offset = app.visualize.row_offset;
                            let old_sel = app.visualize.row_selected;
                            // Special case: if old offset == old_sel (at top), first page down moves offset by 1? But our formula also gives offset 2 for sel14?
                            // For initial sel0 offset0 visible14: new sel =13, new offset =13-14+2=1 => offset 1, but observed offset 2 for 1-indexed? Let's adjust for 0-indexed
                            // For 0-indexed: initial sel0 offset0 visible 14. After page down sel13, offset should be 1? Because sel - visible +2 =13-14+2=1, which matches second observation? For first page down we had sel14 first2? Wait for 60x20 we had sel14 (1-indexed) which is index13, first2 is offset1 (0-indexed). So offset1 matches sel - visible +2 =13-14+2=1 matches.
                            // For initial first d, we had sel14 offset2 for 1-indexed: offset1 (0-indexed) =1? Actually 1-indexed first2 => 0-indexed offset1=1, matches.
                            // So first d offset 1 is sel - visible +2.

                            // But we observed first d offset 2 for 1-indexed first2? Actually 1-indexed first2 => 0-indexed 1, which is sel - visible +2.

                            // So use: new_sel = old_sel + visible -1, new_offset = new_sel - visible +2, but also ensure offset not decreasing?

                            // Let's implement:
                            let new_sel = std::cmp::min(num_rows.saturating_sub(1), old_sel + visible - 1);
                            let new_offset = if new_sel >= visible - 1 {
