fn get_visualize_visible_rows(term_height: usize) -> usize {
    if term_height <= 6 { return 1; }
    term_height - 6 // overhead: top bar 2 + header 1 + separator 1 + footer 1 + maybe 1
}

fn flatten_schema_tree(tree: &[SchemaNode]) -> Vec<usize> {
    // DFS order, starting from root's children? Actually root is included
    let mut flat = Vec::new();
    // Simple DFS from root (index 0)
    if tree.is_empty() { return flat; }
    let mut stack = vec![0];
    while let Some(idx) = stack.pop() {
        flat.push(idx);
        // Push children in reverse order to maintain order
        for &child in tree[idx].children.iter().rev() {
            stack.push(child);
        }
    }
    flat
}

