fn format_byte_array_min_max(data: &[u8], _physical_type: &str) -> String {
    // Try to decode as string or int?
    // For simplicity, if data is short and printable, show as string, else hex?
    // Original shows min/max as something like "1" "4" for int64_list etc.
    // We'll attempt to decode based on physical type: for INT32, decode as i32, etc.
    // For now, just show as string if printable, else NULL?

    // Try to interpret as i32 or i64?
    // For byte array, it may be string like "abc"
    // Let's try to decode as utf8
    if let Ok(s) = std::str::from_utf8(data) {
        if s.chars().all(|c| c.is_alphanumeric() || c.is_whitespace() || c.is_ascii_punctuation()) {
            return s.to_string();
        }
    }
    // Try as i32
    if data.len() == 4 {
        let v = i32::from_le_bytes([data[0], data[1], data[2], data[3]]);
        return v.to_string();
    }
    if data.len() == 8 {
        let v = i64::from_le_bytes([data[0],data[1],data[2],data[3],data[4],data[5],data[6],data[7]]);
        return v.to_string();
    }
    // Fallback to debug
    format!("{:?}", data)
}

fn draw_row_groups(f: &mut Frame, area: Rect, app: &mut App) {
    let chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(30), Constraint::Percentage(70)])
        .split(area);

    draw_schema_tree(f, chunks[0], app, true);

    // Right side: either overview or column detail
    let flat = &app.row_groups.flat_nodes;
    let sel_idx = app.row_groups.schema_selected;
    let node_idx = flat.get(sel_idx).copied().unwrap_or(0);
    let node = app.file.schema_tree.get(node_idx);

    let is_leaf = node.map(|n| n.is_leaf).unwrap_or(false);

    if !is_leaf {
        // Overview
        draw_rg_overview(f, chunks[1], app);
    } else {
        // Column detail
        draw_rg_column_detail(f, chunks[1], app);
    }
