fn draw_metadata(f: &mut Frame, area: Rect, app: &App) {
    // Centered box with file metadata
    // Fields: Format version, Created by, Rows, Columns, Row groups, Size (raw), Size (compressed), Compression ratio, Codecs (cols), Encodings, Avg row size

    let meta = &app.file.metadata;

    // Compute values
    let version_str = meta.version.to_string();
    let created_by = meta.created_by.clone().unwrap_or_else(|| "".to_string());
    let rows = meta.num_rows.to_string();
    let cols = meta.schema.iter().filter(|e| e.num_children.is_none()).count().to_string();
    let rg = meta.row_groups.len().to_string();

    // Calculate raw and compressed sizes
    let mut total_uncompressed: i64 = 0;
    let mut total_compressed: i64 = 0;
    for rg in &meta.row_groups {
        total_uncompressed += rg.total_byte_size;
        for col in &rg.columns {
            total_compressed += col.meta_data.total_compressed_size;
        }
    }
    // For simplicity, use total_byte_size as raw? Actually raw size is sum of uncompressed sizes of columns? Let's use total_uncompressed for raw, total_compressed for compressed?
    // In earlier metadata for alltypes_plain: raw 671 B compressed 671 B, total_byte_size 671.
    // So raw = total_byte_size? Let's see.

    let raw_str = format_size(total_uncompressed);
    let comp_str = format_size(total_compressed);
    let ratio = if total_compressed > 0 {
        total_uncompressed as f64 / total_compressed as f64
    } else {
        1.0
    };
    let ratio_str = format!("{:.2}x", ratio);

    // Codecs: count per codec
    let mut codec_counts: HashMap<String, usize> = HashMap::new();
    for rg in &meta.row_groups {
        for col in &rg.columns {
            let codec_name = compression_name(col.meta_data.codec);
            *codec_counts.entry(codec_name).or_insert(0) += 1;
        }
    }
    let codecs_str = codec_counts.iter().map(|(k,v)| format!("{}({})", k, v)).collect::<Vec<_>>().join(", ");

    // Encodings: collect unique
    let mut enc_set: std::collections::HashSet<String> = std::collections::HashSet::new();
    for rg in &meta.row_groups {
        for col in &rg.columns {
            for &enc in &col.meta_data.encodings {
                enc_set.insert(encoding_name(enc));
            }
        }
    }
    let mut encodings: Vec<String> = enc_set.into_iter().collect();
    encodings.sort();
    let encodings_str = encodings.join(", ");

    let avg_row_size = if meta.num_rows > 0 {
        (total_uncompressed as f64 / meta.num_rows as f64) as i64
    } else { 0 };
    let avg_str = format_size(avg_row_size);

    // Build lines for box
    let lines = vec![
        format!("    Format version {}", version_str),
        format!("        Created by {}", created_by),
        format!("              Rows {}", rows),
        format!("           Columns {}", cols),
        format!("        Row groups {}", rg),
        format!("        Size (raw) {}", raw_str),
        format!(" Size (compressed) {}", comp_str),
        format!(" Compression ratio {}", ratio_str),
        format!("     Codecs (cols) {}", codecs_str),
        format!("         Encodings {}", encodings_str),
        format!("      Avg row size {}", avg_str),
    ];

    let max_line_len = lines.iter().map(|l| l.len()).max().unwrap_or(0) as u16;
    let box_width = max_line_len + 4;
    let box_height = lines.len() as u16 + 2;

    let x = area.x + (area.width.saturating_sub(box_width)) / 2;
    let y = area.y + (area.height.saturating_sub(box_height)) / 2;
    let box_area = Rect { x, y, width: box_width, height: box_height };

    let block = Block::default()
        .borders(Borders::ALL)
        .title(Span::styled("File Metadata", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)))
        .border_style(Style::default().fg(Color::DarkGray));

    // Render block and then paragraphs
    f.render_widget(block, box_area);

    let inner = Rect { x: box_area.x + 1, y: box_area.y + 1, width: box_area.width - 2, height: box_area.height - 2 };

    // For each line, we need to style label and value differently: label bold blue? In original, label was bold blue (maybe Color::Blue)
    // We'll parse each line: label is part before last space? Actually format: "    Format version 1" label is "    Format version" value "1"
    // We'll split by first occurrence of label known.

    let mut para_lines: Vec<Line> = Vec::new();
    for line in lines {
        // Split into label and value: label is trimmed start part up to last 2 spaces? Simplify: find where value starts as last token maybe with spaces? For our lines, we formatted with label and value separated by single space, but original had aligned labels right-aligned.
        // To simplify, we just create styled line: label part bold blue? Let's attempt to detect label as up to last space before value?
        // For "    Format version 1", label = "    Format version", value "1"
        // We can split by rsplitn into 2.

        let parts: Vec<&str> = line.rsplitn(2, ' ').collect();
        if parts.len() == 2 {
            let value = parts[0];
            let label = parts[1];
            let label_span = Span::styled(label.to_string(), Style::default().fg(Color::Blue).add_modifier(Modifier::BOLD));
            let value_span = Span::raw(format!(" {}", value));
            para_lines.push(Line::from(vec![label_span, value_span]));
