fn build_tree_prefix(tree: &[SchemaNode], node_idx: usize) -> String {
    // Build prefix like "   ├─ " etc based on ancestors
    // For simplicity, we will compute depth and for each level whether ancestor is last child

    let mut path: Vec<usize> = Vec::new();
    let mut cur = node_idx;
    while let Some(parent) = tree[cur].parent {
        path.push(parent);
        cur = parent;
    }
    path.reverse();

    let mut prefix = String::new();

    for (i, &ancestor_idx) in path.iter().enumerate() {
        let ancestor = &tree[ancestor_idx];
        // Determine if ancestor's child that leads to node is last child
        // Need to know child position
        // For each ancestor, find which child is the next node in path (or target if last)
        let next_in_path = if i + 1 < path.len() {
            path[i+1]
        } else {
            node_idx
        };
        let is_last = ancestor.children.last().copied() == Some(next_in_path);
        if is_last {
            prefix.push_str("   ");
        } else {
            prefix.push_str("│  ");
        }
    }

    // Now for current node, determine if it's last child of its parent
    if let Some(parent_idx) = tree[node_idx].parent {
        let parent = &tree[parent_idx];
        let is_last = parent.children.last().copied() == Some(node_idx);
        if is_last {
            prefix.push_str("└─ ");
        } else {
            prefix.push_str("├─ ");
        }
    } else {
        prefix.push_str("└─ ");
    }

    prefix
}

