    // For group nodes, we show repetition = "OPTIONAL"/"REQUIRED"/"REPEATED", physical = "group", others empty.

    // For leaf nodes, we need to compute:
    // Repetition (from schema node)
    // Physical (from schema node)
    // Compressed size (from column chunk meta total_compressed_size)
    // Uncompressed size (total_uncompressed_size)
    // Ratio = compressed/uncompressed? Actually original shows ratio like 1.00x etc. Compute compressed/uncompressed? For alltypes_plain, compressed 73 uncompressed 73 ratio 1.00x.
    // Encodings: list of encodings as names
    // Compression: codec name
    // Min, Max, Nulls: from statistics (if present)

    // So we need to build rows for each flat node except root that has physical != group? Or all non-root?

    // Let's implement for schema tab: show stats for all nodes except root, with leaf nodes having actual stats.

    let flat = &app.schema.flat_nodes;
    // Filter to exclude root (index 0)
    let nodes_to_show: Vec<usize> = flat.iter().skip(1).cloned().collect();

    // Build header
    let header_titles = vec!["Repetition", "Physical", "Compressed", "Uncompressed", "Ratio", "Encodings", "Compression", "Min", "Max", "Nulls"];
    // Apply horizontal scroll
    let scroll = app.schema.scroll;

    // Determine visible header columns based on scroll and area width?
    // For simplicity, we will show all columns but scroll horizontally by shifting start
    // Original horizontal scroll moves by column? In small terminal, scroll moved from showing "Repetition Physical" to "Physical Compressed" etc. So it scrolls by one column at a time.

    let mut header_cells = Vec::new();
    for (i, title) in header_titles.iter().enumerate() {
        if i < scroll { continue; }
        // Check if fits
        // We'll just include all remaining
        header_cells.push(Cell::from(*title).style(Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
    }

    let header = Row::new(header_cells).height(1);

    let mut rows = Vec::new();
    for (flat_idx, &node_idx) in nodes_to_show.iter().enumerate() {
        if node_idx >= app.file.schema_tree.len() { continue; }
        let node = &app.file.schema_tree[node_idx];
        let is_selected = flat_idx + 1 == app.schema.selected; // +1 because we skipped root

        // Find column chunk for this node's path
        let col_chunk_opt = if node.is_leaf {
            app.file.metadata.row_groups.first().and_then(|rg| {
                rg.columns.iter().find(|c| c.meta_data.path_in_schema == node.path)
            })
        } else {
            None
        };

        let mut cells: Vec<Cell> = Vec::new();
        let mut all_fields = Vec::new();

        // Repetition
        all_fields.push(node.repetition.clone());
        // Physical
        all_fields.push(node.physical_type.clone());
        // Compressed
        let comp_size = col_chunk_opt.map(|c| format_size(c.meta_data.total_compressed_size));
        all_fields.push(comp_size.unwrap_or_default());
        // Uncompressed
        let uncomp_size = col_chunk_opt.map(|c| format_size(c.meta_data.total_uncompressed_size));
        all_fields.push(uncomp_size.unwrap_or_default());
        // Ratio
        let ratio = if let Some(col) = col_chunk_opt {
            if col.meta_data.total_uncompressed_size > 0 {
                format!("{:.2}x", col.meta_data.total_compressed_size as f64 / col.meta_data.total_uncompressed_size as f64)
            } else {
                "".to_string()
            }
        } else { "".to_string() };
        all_fields.push(ratio);
        // Encodings
        let encodings = if let Some(col) = col_chunk_opt {
            col.meta_data.encodings.iter().map(|&e| encoding_name(e)).collect::<Vec<_>>().join(", ")
        } else { "".to_string() };
        all_fields.push(encodings);
        // Compression
        let comp = col_chunk_opt.map(|c| compression_name(c.meta_data.codec)).unwrap_or_default();
        all_fields.push(comp);
        // Min
        let min_str = col_chunk_opt.and_then(|c| c.meta_data.statistics.as_ref()).and_then(|s| s.min.as_ref()).map(|b| format_byte_array_min_max(b, &node.physical_type)).unwrap_or_else(|| "NULL".to_string());
        // Actually original shows NULL for min/max when not present? For alltypes_plain, min max NULL
        all_fields.push(min_str);
        // Max
        let max_str = col_chunk_opt.and_then(|c| c.meta_data.statistics.as_ref()).and_then(|s| s.max.as_ref()).map(|b| format_byte_array_min_max(b, &node.physical_type)).unwrap_or_else(|| "NULL".to_string());
        all_fields.push(max_str);
        // Nulls
        let nulls = col_chunk_opt.and_then(|c| c.meta_data.statistics.as_ref()).and_then(|s| s.null_count).map(|n| n.to_string()).unwrap_or_else(|| "0".to_string());
        all_fields.push(nulls);

        for (i, field) in all_fields.iter().enumerate() {
            if i < scroll { continue; }
            let style = if is_selected {
                Style::default().fg(Color::Black).bg(Color::Yellow)
            } else {
                Style::default()
            };
            cells.push(Cell::from(field.clone()).style(style));
        }

        rows.push(Row::new(cells).height(1));
    }

    let block = Block::default()
        .borders(Borders::ALL)
        .title(Span::styled("Column Statistics", Style::default().fg(Color::Green).add_modifier(Modifier::BOLD)))
        .border_style(Style::default().fg(Color::DarkGray));

    let constraints: Vec<Constraint> = header_titles.iter().skip(scroll).map(|_| Constraint::Min(10)).collect();

    let table = Table::new(rows, constraints)
        .header(header)
        .block(block)
        .row_highlight_style(Style::default().fg(Color::Black).bg(Color::Yellow));

    f.render_widget(table, area);
}

fn format_byte_array_min_max(data: &[u8], _physical_type: &str) -> String {
    // Try to decode as string or int?
    // For simplicity, if data is short and printable, show as string, else hex?
    // Original shows min/max as something like "1" "4" for int64_list etc.
    // We'll attempt to decode based on physical type: for INT32, decode as i32, etc.
    // For now, just show as string if printable, else NULL?

    // Try to interpret as i32 or i64?
    // For byte array, it may be string like "abc"
    // Let's try to decode as utf8
    if let Ok(s) = std::str::from_utf8(data) {
        if s.chars().all(|c| c.is_alphanumeric() || c.is_whitespace() || c.is_ascii_punctuation()) {
            return s.to_string();
        }
    }
    // Try as i32
    if data.len() == 4 {
        let v = i32::from_le_bytes([data[0], data[1], data[2], data[3]]);
        return v.to_string();
    }
    if data.len() == 8 {
        let v = i64::from_le_bytes([data[0],data[1],data[2],data[3],data[4],data[5],data[6],data[7]]);
        return v.to_string();
    }
    // Fallback to debug
    format!("{:?}", data)
}

fn draw_row_groups(f: &mut Frame, area: Rect, app: &mut App) {
    let chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(30), Constraint::Percentage(70)])
        .split(area);

    draw_schema_tree(f, chunks[0], app, true);

    // Right side: either overview or column detail
    let flat = &app.row_groups.flat_nodes;
    let sel_idx = app.row_groups.schema_selected;
    let node_idx = flat.get(sel_idx).copied().unwrap_or(0);
    let node = app.file.schema_tree.get(node_idx);

    let is_leaf = node.map(|n| n.is_leaf).unwrap_or(false);

    if !is_leaf {
        // Overview
        draw_rg_overview(f, chunks[1], app);
