    }
}

fn draw_rg_overview(f: &mut Frame, area: Rect, app: &App) {
    let rg_idx = app.row_groups.rg_selected;
    let rg = app.file.metadata.row_groups.get(rg_idx);

    if rg.is_none() {
        f.render_widget(Paragraph::new("No row group"), area);
        return;
    }
    let rg = rg.unwrap();

    // Top progress bar for row group
    let title = format!(" Row Group: {} / {} ", rg_idx+1, app.file.metadata.row_groups.len());

    // Split area vertically into parts: progress bar (1), then 4 boxes row, then charts
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(2), // progress bar area (including border)
            Constraint::Length(3), // 4 small boxes
            Constraint::Percentage(50), // compressed vs uncompressed chart
            Constraint::Percentage(50), // compression ratio chart
        ])
        .split(area);

    // Progress bar: block with title and gauge
    let gauge = Gauge::default()
        .block(Block::default().borders(Borders::ALL).title(title))
        .gauge_style(Style::default().fg(Color::Blue))
        .percent(100) // full
        .label("");

    // For custom █ bar as in original, we can use Gauge with 100% shows full blocks?
    f.render_widget(gauge, chunks[0]);

    // 4 small boxes: Rows, Compressed, Uncompressed, Ratio
    let small_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(25),
            Constraint::Percentage(25),
            Constraint::Percentage(25),
            Constraint::Percentage(25),
        ])
        .split(chunks[1]);

    let rows = rg.num_rows;
    let compressed: i64 = rg.columns.iter().map(|c| c.meta_data.total_compressed_size).sum();
    let uncompressed: i64 = rg.columns.iter().map(|c| c.meta_data.total_uncompressed_size).sum();
    let ratio = if uncompressed > 0 { compressed as f64 / uncompressed as f64 } else { 1.0 };

    let total_rows = app.file.metadata.num_rows;
    let total_compressed: i64 = app.file.metadata.row_groups.iter().map(|rg| rg.columns.iter().map(|c| c.meta_data.total_compressed_size).sum::<i64>()).sum();
    let total_uncompressed: i64 = app.file.metadata.row_groups.iter().map(|rg| rg.columns.iter().map(|c| c.meta_data.total_uncompressed_size).sum::<i64>()).sum();
    let total_ratio = if total_uncompressed > 0 { total_compressed as f64 / total_uncompressed as f64 } else { 1.0 };

    let boxes = vec![
        (format!("Rows"), format!("{}", rows), format!("{} / {}", rows, total_rows)),
        (format!("Compressed"), format_size(compressed), format!("{} / {}", format_size(compressed), format_size(total_compressed))),
        (format!("Uncompressed"), format_size(uncompressed), format!("{} / {}", format_size(uncompressed), format_size(total_uncompressed))),
        (format!("Ratio"), format!("{:.2}", ratio), format!("{:.2} / {:.2}", ratio, total_ratio)),
    ];

    for (i, (title, value, bottom)) in boxes.into_iter().enumerate() {
        let block = Block::default().borders(Borders::ALL).title(Span::styled(title, Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)));
        let inner = block.inner(small_chunks[i]);
        f.render_widget(block, small_chunks[i]);

        let para_chunks = Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Min(0), Constraint::Length(1)])
            .split(inner);

        let value_para = Paragraph::new(value).alignment(Alignment::Center).style(Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD));
        f.render_widget(value_para, para_chunks[0]);

        let bottom_para = Paragraph::new(bottom).alignment(Alignment::Center).style(Style::default().fg(Color::Magenta));
        f.render_widget(bottom_para, para_chunks[1]);
    }

    // Charts: Compressed vs Uncompressed (B)
    // For single RG, we need to create datasets

    // For simplicity, we will render a bar chart using ratatui's BarChart? But we have only Chart widget with GraphType Bar?
    // In original, it shows two charts: "Compressed vs Uncompressed (B)" with y axis 0..max, x axis Row Group, with two colors for compressed and uncompressed
    // Second chart "Compression Ratio" with ratio.

    // We'll create a simple bar chart for first

    // Dataset for compressed and uncompressed across row groups

    let mut comp_data: Vec<(f64,f64)> = Vec::new();
    let mut uncomp_data: Vec<(f64,f64)> = Vec::new();
    let mut ratio_data: Vec<(f64,f64)> = Vec::new();

    for (i, rg) in app.file.metadata.row_groups.iter().enumerate() {
        let comp: i64 = rg.columns.iter().map(|c| c.meta_data.total_compressed_size).sum();
        let uncomp: i64 = rg.columns.iter().map(|c| c.meta_data.total_uncompressed_size).sum();
        let r = if uncomp >0 { comp as f64 / uncomp as f64 } else { 0.0 };
        comp_data.push((i as f64, comp as f64));
        uncomp_data.push((i as f64, uncomp as f64));
        ratio_data.push((i as f64, r));
    }

    // For first chart
    let max_y = comp_data.iter().chain(uncomp_data.iter()).map(|(_, y)| *y).fold(0.0, f64::max).max(1.0);

    let datasets = vec![
        Dataset::default().name("Compressed").marker(symbols::Marker::Dot).graph_type(GraphType::Bar).style(Style::default().fg(Color::Blue)).data(&comp_data),
        Dataset::default().name("Uncompressed").marker(symbols::Marker::Dot).graph_type(GraphType::Bar).style(Style::default().fg(Color::Red)).data(&uncomp_data),
    ];

    let chart1 = Chart::new(datasets)
        .block(Block::default().title("Compressed vs Uncompressed (B)").borders(Borders::NONE))
        .x_axis(Axis::default().title("Row Group").bounds([0.0, app.file.metadata.row_groups.len() as f64]))
        .y_axis(Axis::default().title("").bounds([0.0, max_y]).labels(vec!["0".into(), format!("{:.0}", max_y/2.0).into(), format!("{:.0}", max_y).into()]));

    f.render_widget(chart1, chunks[2]);

    // Second chart: Compression Ratio

    let max_ratio = ratio_data.iter().map(|(_, y)| *y).fold(0.0, f64::max).max(1.0);
    let dataset_ratio = Dataset::default().name("Compression Ratio").marker(symbols::Marker::Dot).graph_type(GraphType::Line).style(Style::default().fg(Color::Yellow)).data(&ratio_data);

    let chart2 = Chart::new(vec![dataset_ratio])
        .block(Block::default().title("Compression Ratio").borders(Borders::NONE))
        .x_axis(Axis::default().title("Row Group").bounds([0.0, app.file.metadata.row_groups.len() as f64]))
        .y_axis(Axis::default().title("").bounds([0.0, max_ratio*1.2]).labels(vec!["1.0x".into(), "1.1x".into()]));

    f.render_widget(chart2, chunks[3]);
}

fn draw_rg_column_detail(f: &mut Frame, area: Rect, app: &App) {
    let rg_idx = app.row_groups.rg_selected;
    let rg = app.file.metadata.row_groups.get(rg_idx);

    if rg.is_none() {
        f.render_widget(Paragraph::new("No row group"), area);
        return;
    }
    let rg = rg.unwrap();

    let flat = &app.row_groups.flat_nodes;
    let sel_node_idx = flat.get(app.row_groups.schema_selected).copied().unwrap_or(0);
    let node = &app.file.schema_tree[sel_node_idx];
    let col_path = &node.path;

    let col_chunk = rg.columns.iter().find(|c| &c.meta_data.path_in_schema == col_path);

    if col_chunk.is_none() {
        f.render_widget(Paragraph::new(format!("Column {:?} not found in row group", col_path)), area);
        return;
    }
    let col_chunk = col_chunk.unwrap();

    // Title: Column: "xxx"
    let title = format!(" Column: \"{}\" ", col_chunk.meta_data.path_in_schema.join("."));

    // Layout: top row with 4 small boxes for Statistics, Dict Page, Bloom Filter, Page Stats, then bottom with Metadata and Pages

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // title? Actually title is block title
            Constraint::Length(3), // 4 small boxes
            Constraint::Percentage(50),
            Constraint::Percentage(50),
        ])
        .split(area);

    // Title block
    let title_block = Block::default().borders(Borders::ALL).title(title);
    f.render_widget(title_block, chunks[0]);

    // 4 small boxes
    let small_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(25),
            Constraint::Percentage(25),
            Constraint::Percentage(25),
            Constraint::Percentage(25),
        ])
        .split(chunks[1]);

    // For statistics: check if present
    let has_stats = col_chunk.meta_data.statistics.is_some();
    let has_dict = col_chunk.meta_data.dictionary_page_offset.is_some();
    // Bloom filter not in our metadata parsing yet, assume false
    let has_bloom = false;
    // Page stats? maybe from pages? Assume true if we have pages

    let stats_boxes = vec![
        ("Statistics", has_stats),
        ("Dict Page", has_dict),
        ("Bloom Filter", has_bloom),
        ("Page Stats", true),
    ];

    for (i, (t, has)) in stats_boxes.into_iter().enumerate() {
        let symbol = if has { "✓" } else { "✗" };
        let block = Block::default().borders(Borders::ALL).title(Span::styled(t, Style::default().fg(Color::Cyan)));
        let inner = block.inner(small_chunks[i]);
        f.render_widget(block, small_chunks[i]);
        let para = Paragraph::new(symbol).alignment(Alignment::Center);
        f.render_widget(para, inner);
    }

    // Metadata and Pages

    let bottom_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(40), Constraint::Percentage(60)])
        .split(chunks[2]);

    // Metadata block
    let meta_block = Block::default().borders(Borders::ALL).title("Metadata");
    let meta_inner = meta_block.inner(bottom_chunks[0]);
    f.render_widget(meta_block, bottom_chunks[0]);

    let meta_lines = vec![
        format!("File Offset (B)    {}", col_chunk.file_offset),
        format!("Compressed Size    {}", format_size(col_chunk.meta_data.total_compressed_size)),
        format!("Uncompressed Size  {}", format_size(col_chunk.meta_data.total_uncompressed_size)),
        format!("Compression Ratio  {:.2}x", col_chunk.meta_data.total_compressed_size as f64 / col_chunk.meta_data.total_uncompressed_size as f64),
        format!("Compression Type   {}", compression_name(col_chunk.meta_data.codec)),
    ];
    let meta_para = Paragraph::new(meta_lines.join("\n"));
    f.render_widget(meta_para, meta_inner);

    // Pages block
    let pages_block = Block::default().borders(Borders::ALL).title("Pages");
    let pages_inner = pages_block.inner(bottom_chunks[1]);
    f.render_widget(pages_block, bottom_chunks[1]);

    // For pages, we need to list pages from file
    // We'll attempt to read pages from file data for this column chunk and display

    // For simplicity, show placeholder
    let pages_text = format!("Pages for column {}", col_chunk.meta_data.path_in_schema.join("."));
    f.render_widget(Paragraph::new(pages_text), pages_inner);

    // Lower part: Statistics and maybe more
    // In original, there is also Statistics box below metadata with Min, Max, Null Count, Distinct Count
    // We'll render that in the remaining area chunks[3]

    let lower_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(40), Constraint::Percentage(60)])
        .split(chunks[3]);

    let stats_block = Block::default().borders(Borders::ALL).title("Statistics");
    let stats_inner = stats_block.inner(lower_chunks[0]);
    f.render_widget(stats_block, lower_chunks[0]);

    if let Some(stats) = &col_chunk.meta_data.statistics {
        let null_count = stats.null_count.unwrap_or(0);
        let distinct = stats.distinct_count.map(|c| c.to_string()).unwrap_or_else(|| "N/A".to_string());
        let min = stats.min.as_ref().map(|b| format_byte_array_min_max(b, &format!("{:?}", col_chunk.meta_data.r#type))).unwrap_or_else(|| "".to_string());
        let max = stats.max.as_ref().map(|b| format_byte_array_min_max(b, &format!("{:?}", col_chunk.meta_data.r#type))).unwrap_or_else(|| "".to_string());

        let lines = vec![
            format!("Min                {}", min),
            format!("Max                {}", max),
            format!("Null Count         {}", null_count),
            format!("Distinct Count     {}", distinct),
        ];
        f.render_widget(Paragraph::new(lines.join("\n")), stats_inner);
    }
}
