        tab: Tab::Visualize,
        visualize: VisualizeState { row_selected: 0, row_offset: 0, col_offset: 0 },
        schema: schema_state,
        row_groups: rg_state,
        terminal_height: 0,
    };

    loop {
        terminal.draw(|f| {
            app.terminal_height = f.area().height as usize;
            draw(f, &mut app);
        })?;

        if event::poll(Duration::from_millis(200))? {
            if let Event::Key(k) = event::read()? {
                match k.code {
                    KeyCode::Char('q') | KeyCode::Char('Q') => break,
                    KeyCode::Tab => {
                        let next = (app.tab as usize + 1) % 4;
                        app.tab = Tab::from_usize(next);
                    },
                    KeyCode::BackTab => {
                        let prev = (app.tab as usize + 3) % 4;
                        app.tab = Tab::from_usize(prev);
                    },
                    KeyCode::Down => {
                        match app.tab {
                            Tab::Visualize => {
                                let num_rows = app.file.columns_data.first().map(|c| c.values.len()).unwrap_or(0);
                                if app.visualize.row_selected + 1 < num_rows {
                                    app.visualize.row_selected += 1;
                                    let visible = get_visualize_visible_rows(app.terminal_height);
                                    if app.visualize.row_selected >= app.visualize.row_offset + visible - 1 {
                                        app.visualize.row_offset = app.visualize.row_selected - visible + 2;
                                    }
                                }
                            },
                            Tab::Schema => {
                                if app.schema.selected + 1 < app.schema.flat_nodes.len() {
                                    app.schema.selected += 1;
                                }
                            },
                            Tab::RowGroups => {
                                if app.row_groups.schema_selected + 1 < app.row_groups.flat_nodes.len() {
                                    app.row_groups.schema_selected += 1;
                                }
                            },
                            Tab::Metadata => {},
                        }
                    },
                    KeyCode::Up => {
                        match app.tab {
                            Tab::Visualize => {
                                if app.visualize.row_selected > 0 {
                                    app.visualize.row_selected -= 1;
                                    if app.visualize.row_selected < app.visualize.row_offset {
                                        app.visualize.row_offset = app.visualize.row_selected;
                                    }
                                }
                            },
                            Tab::Schema => {
                                if app.schema.selected > 0 {
                                    app.schema.selected -= 1;
                                }
                            },
                            Tab::RowGroups => {
                                if app.row_groups.schema_selected > 0 {
                                    app.row_groups.schema_selected -= 1;
                                }
                            },
                            Tab::Metadata => {},
                        }
                    },
                    KeyCode::Right => {
                        match app.tab {
                            Tab::Visualize => {
                                let num_cols = app.file.columns_data.len();
                                if app.visualize.col_offset + 1 < num_cols {
                                    app.visualize.col_offset += 1;
                                }
                            },
                            Tab::Schema => {
                                app.schema.scroll += 1;
                            },
                            Tab::RowGroups => {
                                let num_rgs = app.file.metadata.row_groups.len();
                                if num_rgs > 0 {
                                    app.row_groups.rg_selected = (app.row_groups.rg_selected + 1) % num_rgs;
                                }
                            },
                            _ => {},
                        }
                    },
                    KeyCode::Left => {
                        match app.tab {
                            Tab::Visualize => {
                                if app.visualize.col_offset > 0 {
                                    app.visualize.col_offset -= 1;
                                }
                            },
                            Tab::Schema => {
                                if app.schema.scroll > 0 {
                                    app.schema.scroll -= 1;
                                }
                            },
                            Tab::RowGroups => {
                                let num_rgs = app.file.metadata.row_groups.len();
                                if num_rgs > 0 {
                                    if app.row_groups.rg_selected == 0 {
                                        app.row_groups.rg_selected = num_rgs - 1;
                                    } else {
                                        app.row_groups.rg_selected -= 1;
                                    }
                                }
                            },
                            _ => {},
                        }
                    },
                    KeyCode::Char('d') | KeyCode::Char('D') => {
                        if app.tab == Tab::Visualize {
                            let visible = get_visualize_visible_rows(app.terminal_height);
                            let num_rows = app.file.columns_data.first().map(|c| c.values.len()).unwrap_or(0);
                            if num_rows == 0 { continue; }
                            let old_sel = app.visualize.row_selected;
                            let new_sel = std::cmp::min(num_rows - 1, old_sel + visible - 1);
                            let new_offset = if new_sel >= visible - 1 { new_sel - visible + 2 } else { 0 };
                            app.visualize.row_selected = new_sel;
                            app.visualize.row_offset = new_offset;
                        }
                    },
                    KeyCode::Char('u') | KeyCode::Char('U') => {
                        if app.tab == Tab::Visualize {
                            let visible = get_visualize_visible_rows(app.terminal_height);
                            let old_sel = app.visualize.row_selected;
                            let new_sel = old_sel.saturating_sub(visible - 1);
                            app.visualize.row_selected = new_sel;
                            app.visualize.row_offset = new_sel;
                        }
                    },
                    _ => {},
                }
            }
        }
    }

    Ok(())
}

fn get_visualize_visible_rows(term_height: usize) -> usize {
    if term_height <= 6 { return 1; }
    term_height - 6
}

fn flatten_schema_tree(tree: &[SchemaNode]) -> Vec<usize> {
    let mut flat = Vec::new();
    if tree.is_empty() { return flat; }
    let mut stack = vec![0];
    while let Some(idx) = stack.pop() {
        flat.push(idx);
        for &child in tree[idx].children.iter().rev() {
            stack.push(child);
        }
    }
    flat
}

fn draw(f: &mut Frame, app: &mut App) {
    let area = f.area();
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Length(2), Constraint::Min(0), Constraint::Length(1)])
        .split(area);

    // Top bar
    let top_block = Block::default().borders(Borders::ALL).border_style(Style::default().fg(Color::Yellow));
    let inner = top_block.inner(chunks[0]);
    f.render_widget(top_block, chunks[0]);

    let tab_titles = Tab::all_titles();
    let mut x = inner.x;
    for (i, title) in tab_titles.iter().enumerate() {
        let style = if i == app.tab as usize {
            Style::default().add_modifier(Modifier::REVERSED)
        } else {
            Style::default()
        };
        let span = Span::styled(*title, style);
        let width = title.len() as u16 + 2;
        let tab_area = Rect { x, y: inner.y, width, height: 1 };
        f.render_widget(Paragraph::new(Line::from(span)), tab_area);
        x += width + 1;
        if x >= inner.x + inner.width { break; }
    }
    let filename = &app.file.path;
    let filename_span = Span::styled(filename, Style::default().fg(Color::Green));
    let filename_width = filename.len() as u16;
    let filename_x = inner.x + inner.width.saturating_sub(filename_width + 1);
    if filename_x > x {
        let fname_area = Rect { x: filename_x, y: inner.y, width: filename_width, height: 1 };
        f.render_widget(Paragraph::new(Line::from(filename_span)), fname_area);
    }

    // Bottom bar
    let bottom_text = match app.tab {
        Tab::Visualize => "↑/↓ : Row | →/← : Column | u/d : Page - [Tab] Next Tab, [Q]uit",
        Tab::Metadata => "[Tab] Next Tab, [Q]uit",
        Tab::Schema => "←/→ : Scroll, ↑/↓ : Schema - [Tab] Next Tab, [Q]uit",
        Tab::RowGroups => "→/← : Iterate Row Groups, ↑/↓ : Schema - [Tab] Next Tab, [Q]uit",
    };
    let bottom_area = chunks[2];
    let bottom_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Length(8), Constraint::Min(0)])
        .split(bottom_area);
    f.render_widget(Paragraph::new(Span::styled("parqeye", Style::default().fg(Color::Green).add_modifier(Modifier::BOLD))), bottom_chunks[0]);
    let hint_para = Paragraph::new(bottom_text).alignment(Alignment::Right);
    f.render_widget(hint_para, bottom_chunks[1]);

    match app.tab {
        Tab::Visualize => draw_visualize(f, chunks[1], app),
        Tab::Metadata => draw_metadata(f, chunks[1], app),
        Tab::Schema => draw_schema(f, chunks[1], app),
        Tab::RowGroups => draw_row_groups(f, chunks[1], app),
    }
}

fn draw_visualize(f: &mut Frame, area: Rect, app: &App) {
    let num_cols = app.file.columns_data.len();
    let num_rows = app.file.columns_data.first().map(|c| c.values.len()).unwrap_or(0);

    if num_cols == 0 {
        f.render_widget(Paragraph::new("No data"), area);
        return;
    }

    let visible_cols: Vec<(usize, usize)> = {
        let mut cols = Vec::new();
        let mut current_width: usize = 6;
        for i in app.visualize.col_offset..num_cols {
            let col = &app.file.columns_data[i];
            let header_len = col.name.len();
            let mut max_val_len = header_len;
            let visible_rows = get_visualize_visible_rows(app.terminal_height);
            for row_idx in app.visualize.row_offset..std::cmp::min(num_rows, app.visualize.row_offset + visible_rows + 5) {
                if row_idx < col.values.len() {
                    let s = col.values[row_idx].to_display_string();
                    if s.len() > max_val_len {
                        max_val_len = s.len();
                    }
                }
            }
            let col_width = max_val_len + 2;
            if current_width + col_width > area.width as usize {
                if cols.is_empty() {
                    cols.push((i, col_width));
                }
                break;
            }
            cols.push((i, col_width));
            current_width += col_width;
        }
        cols
    };

    let mut header_cells = Vec::new();
    header_cells.push(Cell::from(""));
    for (col_idx, _) in &visible_cols {
        let col = &app.file.columns_data[*col_idx];
        header_cells.push(Cell::from(col.name.clone()).style(Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
    }
    let header = Row::new(header_cells).height(1);

    let visible_rows_count = get_visualize_visible_rows(app.terminal_height);
    let mut rows = Vec::new();
    for row_idx in app.visualize.row_offset..std::cmp::min(num_rows, app.visualize.row_offset + visible_rows_count) {
        let mut cells = Vec::new();
        let row_num_str = format!("{}", row_idx + 1);
        let row_num_style = if row_idx == app.visualize.row_selected {
            Style::default().add_modifier(Modifier::BOLD).add_modifier(Modifier::UNDERLINED).fg(Color::Gray)
        } else {
            Style::default().fg(Color::DarkGray)
        };
        cells.push(Cell::from(row_num_str).style(row_num_style));
        for (col_idx, _) in &visible_cols {
            let col = &app.file.columns_data[*col_idx];
            let val = if row_idx < col.values.len() {
                col.values[row_idx].to_display_string()
            } else {
                "".to_string()
            };
            let style = if row_idx == app.visualize.row_selected {
                Style::default().fg(Color::White).bg(Color::Rgb(60,60,60)).add_modifier(Modifier::BOLD)
            } else {
                Style::default()
            };
            cells.push(Cell::from(val).style(style));
        }
        rows.push(Row::new(cells).height(1));
    }

    let mut constraints: Vec<Constraint> = Vec::new();
    constraints.push(Constraint::Length(6));
    for (_, w) in &visible_cols {
        constraints.push(Constraint::Length(*w as u16));
    }

    let table = Table::new(rows, constraints)
        .header(header)
        .block(Block::default())
        .column_spacing(1);

    f.render_widget(table, area);
}

fn draw_metadata(f: &mut Frame, area: Rect, app: &App) {
    let meta = &app.file.metadata;

    let version_str = meta.version.to_string();
    let created_by = meta.created_by.clone().unwrap_or_else(|| "".to_string());
    let rows = meta.num_rows.to_string();
    let cols = meta.schema.iter().filter(|e| e.num_children.is_none()).count().to_string();
    let rg = meta.row_groups.len().to_string();

    let mut total_uncompressed: i64 = 0;
    let mut total_compressed: i64 = 0;
    for rg in &meta.row_groups {
        total_uncompressed += rg.total_byte_size;
        for col in &rg.columns {
            total_compressed += col.meta_data.total_compressed_size;
        }
    }

    let raw_str = format_size(total_uncompressed);
    let comp_str = format_size(total_compressed);
    let ratio = if total_compressed > 0 { total_uncompressed as f64 / total_compressed as f64 } else { 1.0 };
    let ratio_str = format!("{:.2}x", ratio);

    let mut codec_counts: HashMap<String, usize> = HashMap::new();
    for rg in &meta.row_groups {
        for col in &rg.columns {
            let codec_name = compression_name(col.meta_data.codec);
            *codec_counts.entry(codec_name).or_insert(0) += 1;
        }
    }
    let codecs_str = codec_counts.iter().map(|(k,v)| format!("{}({})", k, v)).collect::<Vec<_>>().join(", ");

    let mut enc_set: HashSet<String> = HashSet::new();
    for rg in &meta.row_groups {
        for col in &rg.columns {
            for &enc in &col.meta_data.encodings {
                enc_set.insert(encoding_name(enc));
            }
        }
    }
    let mut encodings: Vec<String> = enc_set.into_iter().collect();
    encodings.sort();
    let encodings_str = encodings.join(", ");

    let avg_row_size = if meta.num_rows > 0 { (total_uncompressed as f64 / meta.num_rows as f64) as i64 } else { 0 };
    let avg_str = format_size(avg_row_size);

    let lines = vec![
        format!("    Format version {}", version_str),
        format!("        Created by {}", created_by),
        format!("              Rows {}", rows),
        format!("           Columns {}", cols),
        format!("        Row groups {}", rg),
        format!("        Size (raw) {}", raw_str),
        format!(" Size (compressed) {}", comp_str),
        format!(" Compression ratio {}", ratio_str),
        format!("     Codecs (cols) {}", codecs_str),
        format!("         Encodings {}", encodings_str),
        format!("      Avg row size {}", avg_str),
    ];

    let max_line_len = lines.iter().map(|l| l.len()).max().unwrap_or(0) as u16;
    let box_width = max_line_len + 4;
    let box_height = lines.len() as u16 + 2;

    let x = area.x + (area.width.saturating_sub(box_width)) / 2;
    let y = area.y + (area.height.saturating_sub(box_height)) / 2;
    let box_area = Rect { x, y, width: box_width, height: box_height };

    let block = Block::default()
        .borders(Borders::ALL)
        .title(Span::styled("File Metadata", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)))
        .border_style(Style::default().fg(Color::Yellow));

    f.render_widget(block.clone(), box_area);

    let inner = block.inner(box_area);
    let mut para_lines: Vec<Line> = Vec::new();
    for line in lines {
        if let Some(idx) = line.rfind(' ') {
            let (label, value) = line.split_at(idx);
            let label_span = Span::styled(label.to_string(), Style::default().fg(Color::Blue).add_modifier(Modifier::BOLD));
            let value_span = Span::raw(value.to_string());
            para_lines.push(Line::from(vec![label_span, value_span]));
        } else {
            para_lines.push(Line::from(line));
        }
    }

    let para = Paragraph::new(para_lines);
    f.render_widget(para, inner);
}

fn format_size(bytes: i64) -> String {
    if bytes < 1024 {
        format!("{} B", bytes)
    } else if bytes < 1024*1024 {
        format!("{:.2} KiB", bytes as f64 / 1024.0)
    } else {
        format!("{:.2} MiB", bytes as f64 / (1024.0*1024.0))
    }
}

fn compression_name(codec: i32) -> String {
    match codec {
        0 => "UNCOMPRESSED".to_string(),
        1 => "SNAPPY".to_string(),
        2 => "GZIP".to_string(),
        3 => "LZO".to_string(),
        4 => "BROTLI".to_string(),
        5 => "LZ4".to_string(),
        6 => "ZSTD".to_string(),
        7 => "LZ4_RAW".to_string(),
        _ => format!("CODEC_{}", codec),
    }
}

fn encoding_name(enc: i32) -> String {
    match enc {
        0 => "PLAIN".to_string(),
        1 => "GROUP".to_string(),
        2 => "PLAIN_DICTIONARY".to_string(),
        3 => "RLE".to_string(),
        4 => "BIT_PACKED".to_string(),
        5 => "DELTA_BINARY_PACKED".to_string(),
        6 => "DELTA_LENGTH_BYTE_ARRAY".to_string(),
        7 => "DELTA_BYTE_ARRAY".to_string(),
        8 => "RLE_DICTIONARY".to_string(),
        9 => "BYTE_STREAM_SPLIT".to_string(),
        _ => format!("ENC_{}", enc),
    }
}

fn draw_schema(f: &mut Frame, area: Rect, app: &mut App) {
    let chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(30), Constraint::Percentage(70)])
        .split(area);

    draw_schema_tree(f, chunks[0], app, false);
    draw_column_statistics(f, chunks[1], app);
}

fn draw_schema_tree(f: &mut Frame, area: Rect, app: &App, is_row_group: bool) {
    let flat = if is_row_group { &app.row_groups.flat_nodes } else { &app.schema.flat_nodes };
    let selected = if is_row_group { app.row_groups.schema_selected } else { app.schema.selected };

    let title = "Schema Tree";

    let tree = &app.file.schema_tree;

    let is_leaf_selected = if let Some(&node_idx) = flat.get(selected) {
        tree.get(node_idx).map(|n| n.is_leaf).unwrap_or(false)
    } else { false };

    let footer_text = if is_row_group {
        if is_leaf_selected { "Leaf, Group, Selected" } else { "Leaf, Group" }
    } else {
        if is_leaf_selected { "Leaf, Group, Selected" } else { "Leaf, Group" }
    };

    let block = Block::default()
        .borders(Borders::ALL)
        .title(Span::styled(title, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)))
        .title_bottom(Line::from(footer_text))
        .border_style(Style::default().fg(Color::Yellow));

    let inner = block.inner(area);
    f.render_widget(block, area);

    let mut lines: Vec<Line> = Vec::new();
    for (flat_idx, &node_idx) in flat.iter().enumerate() {
        if node_idx >= tree.len() { continue; }
        let node = &tree[node_idx];
        let prefix = build_tree_prefix(tree, node_idx);
        let display = format!("{}{}", prefix, node.name);
        let style = if flat_idx == selected {
            Style::default().fg(Color::Black).bg(Color::Yellow)
        } else {
            Style::default()
        };
        lines.push(Line::from(Span::styled(display, style)));
    }

    let visible_height = inner.height as usize;
    let offset = if selected >= visible_height { selected - visible_height + 1 } else { 0 };
    let visible_lines: Vec<Line> = lines.into_iter().skip(offset).take(visible_height).collect();
    let para = Paragraph::new(visible_lines);
    f.render_widget(para, inner);
}

fn build_tree_prefix(tree: &[SchemaNode], node_idx: usize) -> String {
    let mut path: Vec<usize> = Vec::new();
    let mut cur = node_idx;
    while let Some(parent) = tree[cur].parent {
        path.push(parent);
        cur = parent;
    }
    path.reverse();
    let mut prefix = String::new();
    for (i, &ancestor_idx) in path.iter().enumerate() {
        let next_in_path = if i + 1 < path.len() { path[i+1] } else { node_idx };
        let ancestor = &tree[ancestor_idx];
        let is_last = ancestor.children.last().copied() == Some(next_in_path);
        if is_last {
            prefix.push_str("   ");
        } else {
            prefix.push_str("│  ");
        }
    }
    if let Some(parent_idx) = tree[node_idx].parent {
        let parent = &tree[parent_idx];
        let is_last = parent.children.last().copied() == Some(node_idx);
        if is_last {
            prefix.push_str("└─ ");
        } else {
            prefix.push_str("├─ ");
        }
    } else {
        prefix.push_str("└─ ");
    }
    prefix
}

fn draw_column_statistics(f: &mut Frame, area: Rect, app: &mut App) {
    let flat = &app.schema.flat_nodes;
    let nodes_to_show: Vec<usize> = flat.iter().skip(1).cloned().collect();

    let header_titles = vec!["Repetition", "Physical", "Compressed", "Uncompressed", "Ratio", "Encodings", "Compression", "Min", "Max", "Nulls"];
    let scroll = app.schema.scroll;

    let header_cells: Vec<Cell> = header_titles.iter().enumerate().filter(|(i,_)| *i >= scroll).map(|(_, t)| Cell::from(*t).style(Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))).collect();
    let header = Row::new(header_cells).height(1);

    let mut rows = Vec::new();
    for (flat_idx, &node_idx) in nodes_to_show.iter().enumerate() {
        if node_idx >= app.file.schema_tree.len() { continue; }
        let node = &app.file.schema_tree[node_idx];
        let is_selected = flat_idx + 1 == app.schema.selected;

        let col_chunk_opt = if node.is_leaf {
            app.file.metadata.row_groups.first().and_then(|rg| rg.columns.iter().find(|c| c.meta_data.path_in_schema == node.path))
        } else { None };

        let mut fields = Vec::new();
        fields.push(node.repetition.clone());
        fields.push(node.physical_type.clone());
        fields.push(col_chunk_opt.map(|c| format_size(c.meta_data.total_compressed_size)).unwrap_or_default());
        fields.push(col_chunk_opt.map(|c| format_size(c.meta_data.total_uncompressed_size)).unwrap_or_default());
        fields.push(col_chunk_opt.map(|c| if c.meta_data.total_uncompressed_size>0 { format!("{:.2}x", c.meta_data.total_compressed_size as f64 / c.meta_data.total_uncompressed_size as f64) } else { "".to_string() }).unwrap_or_default());
        fields.push(col_chunk_opt.map(|c| c.meta_data.encodings.iter().map(|&e| encoding_name(e)).collect::<Vec<_>>().join(", ")).unwrap_or_default());
        fields.push(col_chunk_opt.map(|c| compression_name(c.meta_data.codec)).unwrap_or_default());
        fields.push(col_chunk_opt.and_then(|c| c.meta_data.statistics.as_ref()).and_then(|s| s.min.as_ref()).map(|b| format_byte_array_min_max(b)).unwrap_or_else(|| "NULL".to_string()));
        fields.push(col_chunk_opt.and_then(|c| c.meta_data.statistics.as_ref()).and_then(|s| s.max.as_ref()).map(|b| format_byte_array_min_max(b)).unwrap_or_else(|| "NULL".to_string()));
        fields.push(col_chunk_opt.and_then(|c| c.meta_data.statistics.as_ref()).and_then(|s| s.null_count).map(|n| n.to_string()).unwrap_or_else(|| "0".to_string()));

        let cells: Vec<Cell> = fields.into_iter().enumerate().filter(|(i,_)| *i >= scroll).map(|(_, f)| {
            let style = if is_selected { Style::default().fg(Color::Black).bg(Color::Yellow) } else { Style::default() };
            Cell::from(f).style(style)
        }).collect();

        rows.push(Row::new(cells).height(1));
    }

    let block = Block::default()
        .borders(Borders::ALL)
        .title(Span::styled("Column Statistics", Style::default().fg(Color::Green).add_modifier(Modifier::BOLD)))
        .border_style(Style::default().fg(Color::Yellow));

    let table = Table::new(rows, vec![Constraint::Min(10); header_titles.len() - scroll])
        .header(header)
        .block(block);

    f.render_widget(table, area);
}

fn format_byte_array_min_max(data: &[u8]) -> String {
    if let Ok(s) = std::str::from_utf8(data) {
        if s.chars().all(|c| c.is_alphanumeric() || c.is_whitespace() || "!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~".contains(c)) {
            return s.to_string();
        }
    }
    if data.len() == 4 {
        return i32::from_le_bytes([data[0],data[1],data[2],data[3]]).to_string();
    }
    if data.len() == 8 {
        return i64::from_le_bytes([data[0],data[1],data[2],data[3],data[4],data[5],data[6],data[7]]).to_string();
    }
    format!("{:?}", data)
}

fn draw_row_groups(f: &mut Frame, area: Rect, app: &mut App) {
    let chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(30), Constraint::Percentage(70)])
        .split(area);

    draw_schema_tree(f, chunks[0], app, true);

    let flat = &app.row_groups.flat_nodes;
    let sel_idx = app.row_groups.schema_selected;
    let node_idx = flat.get(sel_idx).copied().unwrap_or(0);
    let is_leaf = app.file.schema_tree.get(node_idx).map(|n| n.is_leaf).unwrap_or(false);

    if !is_leaf {
        draw_rg_overview(f, chunks[1], app);
    } else {
        draw_rg_column_detail(f, chunks[1], app);
    }
}

fn draw_rg_overview(f: &mut Frame, area: Rect, app: &App) {
    let rg_idx = app.row_groups.rg_selected;
    let rg_opt = app.file.metadata.row_groups.get(rg_idx);
    if rg_opt.is_none() {
        f.render_widget(Paragraph::new("No row group"), area);
        return;
    }
    let rg = rg_opt.unwrap();

    let title = format!(" Row Group: {} / {} ", rg_idx+1, app.file.metadata.row_groups.len());

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(2),
            Constraint::Length(3),
            Constraint::Percentage(50),
            Constraint::Percentage(50),
        ])
        .split(area);

    let gauge = Gauge::default()
        .block(Block::default().borders(Borders::ALL).title(title))
        .gauge_style(Style::default().fg(Color::Blue))
        .percent(100);

    f.render_widget(gauge, chunks[0]);

    let small_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(25),
            Constraint::Percentage(25),
            Constraint::Percentage(25),
            Constraint::Percentage(25),
        ])
        .split(chunks[1]);

    let rows = rg.num_rows;
    let compressed: i64 = rg.columns.iter().map(|c| c.meta_data.total_compressed_size).sum();
    let uncompressed: i64 = rg.columns.iter().map(|c| c.meta_data.total_uncompressed_size).sum();
    let ratio = if uncompressed > 0 { compressed as f64 / uncompressed as f64 } else { 1.0 };

    let total_rows = app.file.metadata.num_rows;
    let total_compressed: i64 = app.file.metadata.row_groups.iter().map(|rg| rg.columns.iter().map(|c| c.meta_data.total_compressed_size).sum::<i64>()).sum();
    let total_uncompressed: i64 = app.file.metadata.row_groups.iter().map(|rg| rg.columns.iter().map(|c| c.meta_data.total_uncompressed_size).sum::<i64>()).sum();
    let total_ratio = if total_uncompressed > 0 { total_compressed as f64 / total_uncompressed as f64 } else { 1.0 };

    let boxes = vec![
        (format!("Rows"), format!("{}", rows), format!("{} / {}", rows, total_rows)),
        (format!("Compressed"), format_size(compressed), format!("{} / {}", format_size(compressed), format_size(total_compressed))),
        (format!("Uncompressed"), format_size(uncompressed), format!("{} / {}", format_size(uncompressed), format_size(total_uncompressed))),
        (format!("Ratio"), format!("{:.2}", ratio), format!("{:.2} / {:.2}", ratio, total_ratio)),
    ];

    for (i, (t, v, btm)) in boxes.into_iter().enumerate() {
        let block = Block::default().borders(Borders::ALL).title(Span::styled(t, Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)));
        let inner = block.inner(small_chunks[i]);
        f.render_widget(block, small_chunks[i]);
        let pc = Layout::default().direction(Direction::Vertical).constraints([Constraint::Min(0), Constraint::Length(1)]).split(inner);
        f.render_widget(Paragraph::new(v).alignment(Alignment::Center).style(Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)), pc[0]);
        f.render_widget(Paragraph::new(btm).alignment(Alignment::Center).style(Style::default().fg(Color::Magenta)), pc[1]);
    }

    // Charts placeholder
    let chart1 = Paragraph::new("Compressed vs Uncompressed (B) chart").block(Block::default().borders(Borders::ALL));
    f.render_widget(chart1, chunks[2]);
    let chart2 = Paragraph::new("Compression Ratio chart").block(Block::default().borders(Borders::ALL));
    f.render_widget(chart2, chunks[3]);
}

fn draw_rg_column_detail(f: &mut Frame, area: Rect, app: &App) {
    let rg_idx = app.row_groups.rg_selected;
    let rg = match app.file.metadata.row_groups.get(rg_idx) {
        Some(r) => r,
        None => { f.render_widget(Paragraph::new("No RG"), area); return; }
    };
    let flat = &app.row_groups.flat_nodes;
    let sel_node_idx = flat.get(app.row_groups.schema_selected).copied().unwrap_or(0);
    let node = &app.file.schema_tree[sel_node_idx];
    let col_chunk = match rg.columns.iter().find(|c| &c.meta_data.path_in_schema == &node.path) {
        Some(c) => c,
        None => { f.render_widget(Paragraph::new(format!("col not found {:?}", node.path)), area); return; }
    };

    let title = format!(" Column: \"{}\" ", col_chunk.meta_data.path_in_schema.join("."));

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3),
            Constraint::Length(3),
            Constraint::Min(0),
        ])
        .split(area);

    let title_block = Block::default().borders(Borders::ALL).title(title);
    f.render_widget(title_block, chunks[0]);

    let small_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(25); 4])
        .split(chunks[1]);

    let has_stats = col_chunk.meta_data.statistics.is_some();
    let has_dict = col_chunk.meta_data.dictionary_page_offset.is_some();

    let boxes = vec![
        ("Statistics", has_stats),
        ("Dict Page", has_dict),
        ("Bloom Filter", false),
        ("Page Stats", true),
    ];

    for (i, (t, h)) in boxes.into_iter().enumerate() {
        let block = Block::default().borders(Borders::ALL).title(Span::styled(t, Style::default().fg(Color::Cyan)));
        let inner = block.inner(small_chunks[i]);
        f.render_widget(block, small_chunks[i]);
        f.render_widget(Paragraph::new(if h { "✓" } else { "✗" }).alignment(Alignment::Center), inner);
    }

    let bottom_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(40), Constraint::Percentage(60)])
        .split(chunks[2]);

    let meta_block = Block::default().borders(Borders::ALL).title("Metadata");
    let meta_inner = meta_block.inner(bottom_chunks[0]);
    f.render_widget(meta_block, bottom_chunks[0]);

    let meta_lines = vec![
        format!("File Offset (B)    {}", col_chunk.file_offset),
        format!("Compressed Size    {}", format_size(col_chunk.meta_data.total_compressed_size)),
        format!("Uncompressed Size  {}", format_size(col_chunk.meta_data.total_uncompressed_size)),
        format!("Compression Ratio  {:.2}x", col_chunk.meta_data.total_compressed_size as f64 / col_chunk.meta_data.total_uncompressed_size as f64),
        format!("Compression Type   {}", compression_name(col_chunk.meta_data.codec)),
    ];
    f.render_widget(Paragraph::new(meta_lines.join("\n")), meta_inner);

    let pages_block = Block::default().borders(Borders::ALL).title("Pages");
    f.render_widget(Paragraph::new(format!("Pages for {}", node.name)).block(pages_block), bottom_chunks[1]);
}
EOF
