#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Compression {
    Uncompressed = 0,
    Snappy = 1,
    Gzip = 2,
    Lzo = 3,
    Brotli = 4,
    Lz4 = 5,
    Zstd = 6,
    Lz4Raw = 7,
}

impl From<i32> for Compression {
    fn from(v: i32) -> Self {
        match v {
            0 => Compression::Uncompressed,
            1 => Compression::Snappy,
            2 => Compression::Gzip,
            3 => Compression::Lzo,
            4 => Compression::Brotli,
            5 => Compression::Lz4,
            6 => Compression::Zstd,
            7 => Compression::Lz4Raw,
            _ => Compression::Uncompressed,
        }
    }
}

pub fn decompress(compression: Compression, input: &[u8], _uncompressed_size: usize) -> Result<Vec<u8>, String> {
    match compression {
        Compression::Uncompressed => Ok(input.to_vec()),
        Compression::Snappy => decompress_snappy(input),
        Compression::Gzip => {
            Err("GZIP decompression not implemented yet".to_string())
        },
        Compression::Zstd => decompress_zstd(input),
        Compression::Lz4 | Compression::Lz4Raw => decompress_lz4(input),
        _ => Err(format!("Compression {:?} not supported", compression)),
    }
}

fn decompress_snappy(input: &[u8]) -> Result<Vec<u8>, String> {
    fn read_varint(buf: &[u8]) -> Option<(usize, usize)> {
        let mut result: usize = 0;
        let mut shift = 0;
        let mut pos = 0;
        for _ in 0..10 {
            if pos >= buf.len() { return None; }
            let b = buf[pos];
            pos += 1;
            result |= ((b & 0x7f) as usize) << shift;
            if (b & 0x80) == 0 { return Some((result, pos)); }
            shift += 7;
        }
        None
    }

    let (uncompressed_len, header_len) = match read_varint(input) {
        Some(v) => v,
        None => (0, 0),
    };

    let compressed_data = if header_len > 0 && header_len < 10 {
        &input[header_len..]
    } else {
        input
    };

    decompress_snappy_raw(compressed_data, uncompressed_len)
}

fn decompress_snappy_raw(input: &[u8], _expected_len: usize) -> Result<Vec<u8>, String> {
    let mut output = Vec::with_capacity(1024);
    let mut pos = 0;
    while pos < input.len() {
        let tag = input[pos];
        pos += 1;
        let tag_type = tag & 0x03;
        if tag_type == 0 {
            let mut len = (tag >> 2) as usize;
            if len < 60 {
                len += 1;
            } else {
                let extra = (len - 60 + 1) as usize;
                if pos + extra > input.len() { return Err("snappy literal length overflow".to_string()); }
                let mut l = 0usize;
                for i in 0..extra {
                    l |= (input[pos + i] as usize) << (8 * i);
                }
                pos += extra;
                len = l + 1;
            }
            if pos + len > input.len() {
                return Err(format!("snappy literal data overflow: pos {} len {} input len {}", pos, len, input.len()));
            }
            output.extend_from_slice(&input[pos..pos+len]);
            pos += len;
        } else {
            let (copy_len, offset) = match tag_type {
                1 => {
                    let len = ((tag >> 2) & 0x07) as usize + 4;
                    if pos >= input.len() { return Err("snappy copy 1-byte offset missing".to_string()); }
                    let offset = (((tag as usize) >> 5) << 8) | (input[pos] as usize);
                    pos += 1;
                    (len, offset)
                },
                2 => {
                    let len = ((tag >> 2) as usize) + 4;
                    if pos + 2 > input.len() { return Err("snappy copy 2-byte offset missing".to_string()); }
                    let offset = (input[pos] as usize) | ((input[pos+1] as usize) << 8);
                    pos += 2;
                    (len, offset)
                },
                3 => {
                    let len = ((tag >> 2) as usize) + 4;
                    if pos + 4 > input.len() { return Err("snappy copy 4-byte offset missing".to_string()); }
                    let offset = (input[pos] as usize) | ((input[pos+1] as usize) << 8) | ((input[pos+2] as usize) << 16) | ((input[pos+3] as usize) << 24);
                    pos += 4;
                    (len, offset)
                },
                _ => unreachable!(),
            };
            if offset == 0 || offset > output.len() {
                return Err(format!("snappy invalid offset {} output len {}", offset, output.len()));
            }
            let start = output.len() - offset;
            for i in 0..copy_len {
                let b = output[start + i];
                output.push(b);
            }
        }
    }
    Ok(output)
}

fn decompress_zstd(input: &[u8]) -> Result<Vec<u8>, String> {
    // Try to use external zstd command if available? Use std::process?
    // We'll attempt to use libzstd via dynamic loading manually with dlopen? Simpler: try to call zstd via command line if installed
    // Check if zstd binary exists
    // For now, we will attempt to use pure Rust? Not possible without crate.
    // Alternative: Use Python? Not.

    // We have libzstd.so.1, we can attempt to load it via dlopen using libc? Let's try to use unsafe dlopen via libloading? But libloading not available.

    // Instead, we can try to use the `zstd` executable to decompress if it exists

    // For parquet ZSTD, the frame contains decompressed size in header. We could try to use std::process::Command to run `zstd -d -c` with input on stdin.

    use std::process::{Command, Stdio};
    use std::io::Write;

    let mut child = Command::new("zstd")
        .arg("-d")
        .arg("-c")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .map_err(|e| format!("zstd spawn error: {}", e))?;

    {
        let stdin = child.stdin.as_mut().ok_or("no stdin")?;
        stdin.write_all(input).map_err(|e| format!("zstd write error: {}", e))?;
    }

    let output = child.wait_with_output().map_err(|e| format!("zstd wait error: {}", e))?;
    if !output.status.success() {
        return Err(format!("zstd decompress failed: {}", String::from_utf8_lossy(&output.stderr)));
    }
    Ok(output.stdout)
}

fn decompress_lz4(input: &[u8]) -> Result<Vec<u8>, String> {
    // Try using lz4 command
    use std::process::{Command, Stdio};
    use std::io::Write;

    let mut child = Command::new("lz4")
        .arg("-d")
        .arg("-c")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .map_err(|e| format!("lz4 spawn error: {}", e))?;

    {
        let stdin = child.stdin.as_mut().ok_or("no stdin")?;
        stdin.write_all(input).map_err(|e| format!("lz4 write error: {}", e))?;
    }

    let output = child.wait_with_output().map_err(|e| format!("lz4 wait error: {}", e))?;
    if !output.status.success() {
        return Err(format!("lz4 decompress failed: {}", String::from_utf8_lossy(&output.stderr)));
    }
    Ok(output.stdout)
}
