#[derive(Debug, Clone)]
pub enum ParquetValue {
    Null,
    Boolean(bool),
    Int32(i32),
    Int64(i64),
    Float(f32),
    Double(f64),
    ByteArray(Vec<u8>),
    FixedLenByteArray(Vec<u8>),
    Int96([u8;12]),
    String(String),
}

impl ParquetValue {
    pub fn to_display_string(&self) -> String {
        match self {
            ParquetValue::Null => "NULL".to_string(),
            ParquetValue::Boolean(b) => if *b { "true".to_string() } else { "false".to_string() },
            ParquetValue::Int32(i) => i.to_string(),
            ParquetValue::Int64(i) => i.to_string(),
            ParquetValue::Float(f) => {
                if f.fract() == 0.0 { format!("{:.1}", f) } else { format!("{}", f) }
            },
            ParquetValue::Double(d) => {
                if d.fract() == 0.0 { format!("{:.1}", d) } else { format!("{}", d) }
            },
            ParquetValue::ByteArray(b) => {
                let mut s = String::new();
                s.push_str("b\"");
                for &c in b {
                    match c {
                        b'"' => s.push_str("\\\""),
                        b'\\' => s.push_str("\\\\"),
                        b'\n' => s.push_str("\\n"),
                        b'\r' => s.push_str("\\r"),
                        b'\t' => s.push_str("\\t"),
                        0..=31 | 127..=255 => {
                            if c >= 32 && c <= 126 {
                                s.push(c as char);
                            } else {
                                s.push_str(&format!("\\x{:02x}", c));
                            }
                        },
                        _ => s.push(c as char),
                    }
                }
                s.push('"');
                s
            },
            ParquetValue::FixedLenByteArray(b) => {
                ParquetValue::ByteArray(b.clone()).to_display_string()
            },
            ParquetValue::Int96(b) => {
                let nanos = i64::from_le_bytes([b[0],b[1],b[2],b[3],b[4],b[5],b[6],b[7]]);
                let julian = i32::from_le_bytes([b[8],b[9],b[10],b[11]]) as i64;
                let (year, month, day) = jd_to_date(julian);
                let hour = (nanos / 3_600_000_000_000) % 24;
                let minute = (nanos / 60_000_000_000) % 60;
                let second = (nanos / 1_000_000_000) % 60;
                let remaining_nanos = nanos % 1_000_000_000;
                if remaining_nanos == 0 {
                    format!("{:04}-{:02}-{:02} {:02}:{:02}:{:02}", year, month, day, hour, minute, second)
                } else {
                    let millis = remaining_nanos / 1_000_000;
                    let micros = (remaining_nanos % 1_000_000) / 1000;
                    if micros == 0 {
                        format!("{:04}-{:02}-{:02} {:02}:{:02}:{:02}.{:03}", year, month, day, hour, minute, second, millis)
                    } else {
                        format!("{:04}-{:02}-{:02} {:02}:{:02}:{:02}.{:06}", year, month, day, hour, minute, second, remaining_nanos/1000)
                    }
                }
            },
            ParquetValue::String(s) => s.clone(),
        }
    }
}

fn jd_to_date(jd: i64) -> (i32, u32, u32) {
    let mut l = jd + 68569;
    let n = (4 * l) / 146097;
    l = l - (146097 * n + 3) / 4;
    let i = (4000 * (l + 1)) / 1461001;
    l = l - (1461 * i) / 4 + 31;
    let j = (80 * l) / 2447;
    let day = l - (2447 * j) / 80;
    l = j / 11;
    let month = j + 2 - 12 * l;
    let year = 100 * (n - 49) + i + l;
    (year as i32, month as u32, day as u32)
}

fn repetition_str(v: i32) -> String {
    match v {
        0 => "REQUIRED".to_string(),
        1 => "OPTIONAL".to_string(),
        2 => "REPEATED".to_string(),
        _ => format!("REP_{}", v),
    }
}

fn physical_type_str(v: i32) -> String {
    match v {
        0 => "BOOLEAN".to_string(),
        1 => "INT32".to_string(),
        2 => "INT64".to_string(),
        3 => "INT96".to_string(),
        4 => "FLOAT".to_string(),
        5 => "DOUBLE".to_string(),
        6 => "BYTE_ARRAY".to_string(),
        7 => "FIXED_LEN_BYTE_ARRAY".to_string(),
        _ => format!("TYPE_{}", v),
    }
}

pub fn read_parquet_file(path: &Path) -> Result<ParquetFile, String> {
    let mut file = File::open(path).map_err(|e| format!("Parquet error: {}", e))?;
    let mut buf = Vec::new();
    file.read_to_end(&mut buf).map_err(|e| format!("Parquet error: {}", e))?;

    if buf.len() < 8 {
        return Err("Invalid Parquet file. Corrupt footer".to_string());
    }
    let magic = &buf[buf.len()-4..];
    if magic != b"PAR1" {
        if magic == b"PARE" {
            return Err("Parquet file has an encrypted footer but the encryption feature is disabled".to_string());
        }
        return Err("Invalid Parquet file. Corrupt footer".to_string());
    }
    let footer_len = u32::from_le_bytes([buf[buf.len()-8], buf[buf.len()-7], buf[buf.len()-6], buf[buf.len()-5]]) as usize;
    if footer_len > buf.len() - 8 {
        return Err("Invalid Parquet file. Corrupt footer".to_string());
    }
    let footer_start = buf.len() - 8 - footer_len;
    let footer_bytes = &buf[footer_start..footer_start+footer_len];

    let metadata = parse_file_metadata(footer_bytes).map_err(|e| format!("Parquet error: {}", e))?;

    let schema_tree = build_schema_tree(&metadata.schema)?;

    let leaf_nodes: Vec<(usize, Vec<String>)> = {
        let mut leaves = Vec::new();
        for (idx, node) in schema_tree.iter().enumerate() {
            if node.is_leaf {
                leaves.push((idx, node.path.clone()));
            }
        }
        leaves
    };

    let mut columns_data: Vec<ColumnData> = Vec::new();

    for (leaf_idx, path_vec) in &leaf_nodes {
        let node = &schema_tree[*leaf_idx];
        let mut all_values: Vec<ParquetValue> = Vec::new();
        for rg in &metadata.row_groups {
            for col_chunk in &rg.columns {
                if col_chunk.meta_data.path_in_schema == *path_vec {
                    match read_column_chunk(&buf, col_chunk, &node) {
                        Ok(values) => all_values.extend(values),
                        Err(e) => {
                            eprintln!("DEBUG error reading chunk for {:?}: {}", path_vec, e);
                        }
                    }
                }
            }
        }
        columns_data.push(ColumnData {
            name: node.name.clone(),
            path: path_vec.clone(),
            physical_type: node.physical_type.clone(),
            values: all_values,
        });
    }

    let path_str = path.to_string_lossy().to_string();

    Ok(ParquetFile {
        path: path_str,
        metadata,
        schema_tree,
        columns_data,
        row_groups: Vec::new(),
        file_data: buf,
    })
}

fn build_schema_tree(schema: &[crate::parquet::SchemaElement]) -> Result<Vec<SchemaNode>, String> {
    if schema.is_empty() { return Err("empty schema".to_string()); }

    struct StackItem { idx: usize, remaining: i32, }

    let mut nodes: Vec<SchemaNode> = Vec::new();
    let mut stack: Vec<StackItem> = Vec::new();

    for (i, elem) in schema.iter().enumerate() {
        let name = elem.name.clone();
        let repetition = elem.repetition.map(|r| repetition_str(r)).unwrap_or_else(|| "".to_string());
        let physical = elem.r#type.map(|t| physical_type_str(t)).unwrap_or_else(|| "group".to_string());
        let is_leaf = elem.num_children.is_none();

        let parent_path = if let Some(parent) = stack.last() {
            nodes[parent.idx].path.clone()
        } else { Vec::new() };

        let mut path = parent_path;
        if i == 0 {
            path = Vec::new();
        } else {
            path.push(name.clone());
        }

        let node = SchemaNode {
            name: name.clone(),
            path: if i==0 { Vec::new() } else { path.clone() },
            repetition: repetition.clone(),
            physical_type: physical.clone(),
            logical_type: "".to_string(),
            children: Vec::new(),
            parent: stack.last().map(|s| s.idx),
            is_leaf,
            max_definition_level: 0,
            max_repetition_level: 0,
        };

        let idx = nodes.len();
        nodes.push(node);

        if let Some(parent) = stack.last_mut() {
            nodes[parent.idx].children.push(idx);
            parent.remaining -= 1;
        }

        if let Some(num_children) = elem.num_children {
            stack.push(StackItem { idx, remaining: num_children });
        }

        while let Some(top) = stack.last() {
            if top.remaining == 0 {
                stack.pop();
            } else { break; }
        }
    }

    fn compute_levels(nodes: &mut [SchemaNode], idx: usize, def: i32, rep: i32) {
        if idx >= nodes.len() { return; }
        let (children, repetition) = {
            let node = &nodes[idx];
            (node.children.clone(), node.repetition.clone())
        };
        nodes[idx].max_definition_level = def;
        nodes[idx].max_repetition_level = rep;
        let new_def = if repetition == "OPTIONAL" || repetition == "REPEATED" { def + 1 } else { def };
        let new_rep = if repetition == "REPEATED" { rep + 1 } else { rep };
        for child in children {
            compute_levels(nodes, child, new_def, new_rep);
        }
    }

    if !nodes.is_empty() {
        compute_levels(&mut nodes, 0, 0, 0);
    }

    Ok(nodes)
}

fn read_column_chunk(file_buf: &[u8], col_chunk: &ColumnChunk, schema_node: &SchemaNode) -> Result<Vec<ParquetValue>, String> {
    let mut values: Vec<ParquetValue> = Vec::new();

    let start_offset = col_chunk.meta_data.dictionary_page_offset.unwrap_or(col_chunk.meta_data.data_page_offset) as usize;
    let total_size = col_chunk.meta_data.total_compressed_size as usize;

    let mut offset = start_offset;
    let end_offset = start_offset + total_size;

    let mut dictionary: Option<Vec<ParquetValue>> = None;

    while offset < end_offset && offset < file_buf.len() {
        let (page_header, header_end) = parse_page_header(file_buf, offset).map_err(|e| format!("page header error: {}", e))?;
        let compressed_size = page_header.compressed_page_size as usize;
        let uncompressed_size = page_header.uncompressed_page_size as usize;
        let data_start = header_end;
        let data_end = data_start + compressed_size;
        if data_end > file_buf.len() {
            return Err("page data overflow".to_string());
        }
        let compressed_data = &file_buf[data_start..data_end];

        let codec = Compression::from(col_chunk.meta_data.codec);
        let decompressed = decompress(codec, compressed_data, uncompressed_size).map_err(|e| format!("decompress error: {}", e))?;

        eprintln!("DEBUG page type {} comp {} uncomp {} data len {} dict len {:?}", page_header.page_type, compressed_size, uncompressed_size, decompressed.len(), dictionary.as_ref().map(|d| d.len()));

        match page_header.page_type {
            2 => {
                let num_values = page_header.dictionary_page_header.as_ref().map(|h| h.num_values).unwrap_or(0) as usize;
                let dict_vals = decode_dictionary_page(&decompressed, &schema_node.physical_type, num_values)?;
                eprintln!("DEBUG dict vals {:?}", dict_vals.iter().map(|v| v.to_display_string()).collect::<Vec<_>>());
                dictionary = Some(dict_vals);
            },
            0 => {
                let dph = page_header.data_page_header.as_ref().ok_or("missing data page header")?;
                eprintln!("DEBUG data page header num_values {} encoding {} def_enc {} rep_enc {}", dph.num_values, dph.encoding, dph.definition_level_encoding, dph.repetition_level_encoding);
                let vals = decode_data_page(&decompressed, dph, &schema_node, dictionary.as_ref())?;
                eprintln!("DEBUG decoded data page values len {}: {:?}", vals.len(), vals.iter().take(5).map(|v| v.to_display_string()).collect::<Vec<_>>());
                values.extend(vals);
            },
            3 => {
                let dph = page_header.data_page_header_v2.as_ref().ok_or("missing data page v2 header")?;
                let vals = decode_data_page_v2(&decompressed, dph, &schema_node, dictionary.as_ref())?;
                values.extend(vals);
            },
            _ => {}
        }

        offset = data_end;
    }

    Ok(values)
}

fn decode_dictionary_page(data: &[u8], physical_type: &str, num_values: usize) -> Result<Vec<ParquetValue>, String> {
    match physical_type {
        "INT32" => {
            let ints = decode_plain_int32(data);
            Ok(ints.into_iter().map(|v| ParquetValue::Int32(v)).collect())
        },
        "INT64" => {
            let ints = decode_plain_int64(data);
            Ok(ints.into_iter().map(|v| ParquetValue::Int64(v)).collect())
        },
        "FLOAT" => {
            let floats = decode_plain_float(data);
            Ok(floats.into_iter().map(|v| ParquetValue::Float(v)).collect())
        },
        "DOUBLE" => {
            let doubles = decode_plain_double(data);
            Ok(doubles.into_iter().map(|v| ParquetValue::Double(v)).collect())
        },
        "BYTE_ARRAY" => {
            let arrays = decode_plain_byte_array(data);
            Ok(arrays.into_iter().map(|b| ParquetValue::ByteArray(b)).collect())
        },
        "BOOLEAN" => {
            let mut vals = Vec::new();
            for i in 0..num_values {
                let byte_idx = i / 8;
                let bit_idx = i % 8;
                if byte_idx < data.len() {
                    let b = (data[byte_idx] >> bit_idx) & 1;
                    vals.push(ParquetValue::Boolean(b != 0));
                }
            }
            Ok(vals)
        },
        "INT96" => {
            let mut vals = Vec::new();
            let mut pos = 0;
            while pos + 12 <= data.len() && vals.len() < num_values {
                let mut arr = [0u8;12];
                arr.copy_from_slice(&data[pos..pos+12]);
                vals.push(ParquetValue::Int96(arr));
                pos += 12;
            }
            Ok(vals)
        },
        "FIXED_LEN_BYTE_ARRAY" => {
            if num_values == 0 { return Ok(vec![]); }
            let fixed_len = data.len() / num_values;
            let mut vals = Vec::new();
            for i in 0..num_values {
                let start = i * fixed_len;
                let end = start + fixed_len;
                if end <= data.len() {
                    vals.push(ParquetValue::FixedLenByteArray(data[start..end].to_vec()));
                }
            }
            Ok(vals)
        },
        "group" => Ok(vec![]),
        _ => Ok(vec![]),
    }
}

fn decode_data_page(data: &[u8], dph: &crate::parquet::DataPageHeader, schema_node: &SchemaNode, dictionary: Option<&Vec<ParquetValue>>) -> Result<Vec<ParquetValue>, String> {
    let mut pos = 0;

    if schema_node.max_repetition_level > 0 {
        if pos + 4 > data.len() { return Err("rep levels length overflow".to_string()); }
        let len = u32::from_le_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]) as usize;
        pos += 4;
        if pos + len > data.len() { return Err("rep levels data overflow".to_string()); }
        pos += len;
    }

    let mut def_levels: Vec<i64> = Vec::new();
    if schema_node.max_definition_level > 0 {
        if pos + 4 > data.len() { return Err("def levels length overflow".to_string()); }
        let len = u32::from_le_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]) as usize;
        pos += 4;
        if pos + len > data.len() { return Err("def levels data overflow".to_string()); }
        let def_data = &data[pos..pos+len];
        let bit_width = ((schema_node.max_definition_level as f64 + 1.0).log2().ceil() as u8).max(1);
        def_levels = decode_levels_rle(def_data, bit_width, dph.num_values as usize);
        pos += len;
        eprintln!("DEBUG def_levels len {} {:?}", def_levels.len(), def_levels);
    } else {
        def_levels = vec![1; dph.num_values as usize];
    }

    let remaining = &data[pos..];
    eprintln!("DEBUG remaining len {} for encoding {}", remaining.len(), dph.encoding);

    let max_def = schema_node.max_definition_level;
    let non_null_count = def_levels.iter().filter(|&&l| l == max_def as i64).count();
    eprintln!("DEBUG max_def {} non_null {}", max_def, non_null_count);

    let encoding = Encoding::from(dph.encoding);

    let mut decoded_values: Vec<ParquetValue> = Vec::new();

    match encoding {
        Encoding::Plain => {
            decoded_values = decode_plain_page(remaining, &schema_node.physical_type, non_null_count)?;
        },
        Encoding::PlainDictionary | Encoding::RleDictionary => {
            if remaining.is_empty() { return Err("empty dict indices".to_string()); }
            let bit_width = remaining[0];
            let rle_data = &remaining[1..];
            eprintln!("DEBUG dict bit_width {} rle_data len {}", bit_width, rle_data.len());
            let indices = decode_levels_rle(rle_data, bit_width, non_null_count);
            eprintln!("DEBUG indices {:?}", indices);
            if let Some(dict) = dictionary {
                for idx in indices {
                    let i = idx as usize;
                    if i < dict.len() { decoded_values.push(dict[i].clone()); } else { decoded_values.push(ParquetValue::Null); }
                }
            } else {
                return Err("dictionary missing".to_string());
            }
        },
        Encoding::Rle => {
            if schema_node.physical_type == "BOOLEAN" {
                let indices = decode_levels_rle(remaining, 1, non_null_count);
                for v in indices { decoded_values.push(ParquetValue::Boolean(v != 0)); }
            } else {
                decoded_values = decode_plain_page(remaining, &schema_node.physical_type, non_null_count)?;
            }
        },
        Encoding::ByteStreamSplit => {
            decoded_values = decode_byte_stream_split(remaining, &schema_node.physical_type, non_null_count)?;
        },
        Encoding::DeltaBinaryPacked => {
            let vals = decode_delta_binary_packed(remaining, &schema_node.physical_type)?;
            for v in vals.into_iter().take(non_null_count) { decoded_values.push(v); }
        },
        _ => {
            decoded_values = decode_plain_page(remaining, &schema_node.physical_type, non_null_count).unwrap_or_else(|_| Vec::new());
        }
    }

    let mut result: Vec<ParquetValue> = Vec::with_capacity(dph.num_values as usize);
    let mut decoded_idx = 0;
    for &def in &def_levels {
        if def == max_def as i64 {
            if decoded_idx < decoded_values.len() {
                result.push(decoded_values[decoded_idx].clone());
                decoded_idx += 1;
            } else {
                result.push(ParquetValue::Null);
            }
        } else {
            result.push(ParquetValue::Null);
        }
    }

    Ok(result)
}

fn decode_data_page_v2(data: &[u8], dph: &crate::parquet::DataPageHeaderV2, schema_node: &SchemaNode, dictionary: Option<&Vec<ParquetValue>>) -> Result<Vec<ParquetValue>, String> {
    let mut pos = 0;
    let rep_len = dph.repetition_levels_byte_length as usize;
    if rep_len > 0 {
        if pos + rep_len > data.len() { return Err("rep levels v2 overflow".to_string()); }
        pos += rep_len;
    }
    let def_len = dph.definition_levels_byte_length as usize;
    let mut def_levels: Vec<i64> = Vec::new();
    if def_len > 0 {
        if pos + def_len > data.len() { return Err("def levels v2 overflow".to_string()); }
        let def_data = &data[pos..pos+def_len];
        let bit_width = ((schema_node.max_definition_level as f64 + 1.0).log2().ceil() as u8).max(1);
        def_levels = decode_levels_rle(def_data, bit_width, dph.num_values as usize);
        pos += def_len;
    } else {
        def_levels = vec![schema_node.max_definition_level as i64; dph.num_values as usize];
    }

    let remaining = &data[pos..];
    let max_def = schema_node.max_definition_level;
    let non_null_count = if def_levels.is_empty() { dph.num_values as usize } else { def_levels.iter().filter(|&&l| l == max_def as i64).count() };

    let encoding = Encoding::from(dph.encoding);
    let mut decoded_values: Vec<ParquetValue> = Vec::new();

    match encoding {
        Encoding::Plain => {
            decoded_values = decode_plain_page(remaining, &schema_node.physical_type, non_null_count)?;
        },
        Encoding::PlainDictionary | Encoding::RleDictionary => {
            if remaining.is_empty() { return Ok(vec![ParquetValue::Null; dph.num_values as usize]); }
            let bit_width = remaining[0];
            let rle_data = &remaining[1..];
            let indices = decode_levels_rle(rle_data, bit_width, non_null_count);
            if let Some(dict) = dictionary {
                for idx in indices {
                    let i = idx as usize;
                    if i < dict.len() { decoded_values.push(dict[i].clone()); } else { decoded_values.push(ParquetValue::Null); }
                }
            }
        },
        Encoding::Rle => {
            if schema_node.physical_type == "BOOLEAN" {
                let indices = decode_levels_rle(remaining, 1, non_null_count);
                for v in indices { decoded_values.push(ParquetValue::Boolean(v != 0)); }
            } else {
                decoded_values = decode_plain_page(remaining, &schema_node.physical_type, non_null_count)?;
            }
        },
        Encoding::ByteStreamSplit => {
            decoded_values = decode_byte_stream_split(remaining, &schema_node.physical_type, non_null_count)?;
        },
        Encoding::DeltaBinaryPacked => {
            let vals = decode_delta_binary_packed(remaining, &schema_node.physical_type)?;
            for v in vals.into_iter().take(non_null_count) { decoded_values.push(v); }
        },
        _ => {
            decoded_values = decode_plain_page(remaining, &schema_node.physical_type, non_null_count).unwrap_or_else(|_| Vec::new());
        }
    }

    let mut result: Vec<ParquetValue> = Vec::new();
    let mut decoded_idx = 0;
    if def_levels.is_empty() {
        result = decoded_values;
    } else {
        for &def in &def_levels {
            if def == max_def as i64 {
                if decoded_idx < decoded_values.len() {
                    result.push(decoded_values[decoded_idx].clone());
                    decoded_idx += 1;
                } else {
                    result.push(ParquetValue::Null);
                }
            } else {
                result.push(ParquetValue::Null);
            }
        }
    }

    Ok(result)
}

fn decode_levels_rle(data: &[u8], bit_width: u8, num_values: usize) -> Vec<i64> {
    let mut decoder = crate::encoding::RleDecoder::new(data.to_vec(), bit_width);
    let mut out = Vec::with_capacity(num_values);
    for _ in 0..num_values {
        if let Some(v) = decoder.next() {
            out.push(v);
        } else { break; }
    }
    out
}

fn decode_plain_page(data: &[u8], physical_type: &str, num_values: usize) -> Result<Vec<ParquetValue>, String> {
    match physical_type {
        "INT32" => {
            let ints = decode_plain_int32(data);
            Ok(ints.into_iter().take(num_values).map(|v| ParquetValue::Int32(v)).collect())
        },
        "INT64" => {
            let ints = decode_plain_int64(data);
            Ok(ints.into_iter().take(num_values).map(|v| ParquetValue::Int64(v)).collect())
        },
        "FLOAT" => {
            let floats = decode_plain_float(data);
            Ok(floats.into_iter().take(num_values).map(|v| ParquetValue::Float(v)).collect())
        },
        "DOUBLE" => {
            let doubles = decode_plain_double(data);
            Ok(doubles.into_iter().take(num_values).map(|v| ParquetValue::Double(v)).collect())
        },
        "BYTE_ARRAY" => {
            let arrays = decode_plain_byte_array(data);
            Ok(arrays.into_iter().take(num_values).map(|b| ParquetValue::ByteArray(b)).collect())
        },
        "BOOLEAN" => {
            let mut vals = Vec::new();
            for i in 0..num_values {
                let byte_idx = i / 8;
                let bit_idx = i % 8;
                if byte_idx < data.len() {
                    let b = (data[byte_idx] >> bit_idx) & 1;
                    vals.push(ParquetValue::Boolean(b != 0));
                } else {
                    vals.push(ParquetValue::Boolean(false));
                }
            }
            Ok(vals)
        },
        "INT96" => {
            let mut vals = Vec::new();
            let mut pos = 0;
            while pos + 12 <= data.len() && vals.len() < num_values {
                let mut arr = [0u8;12];
                arr.copy_from_slice(&data[pos..pos+12]);
                vals.push(ParquetValue::Int96(arr));
                pos += 12;
            }
            Ok(vals)
        },
        "FIXED_LEN_BYTE_ARRAY" => {
            if num_values == 0 { return Ok(vec![]); }
            let fixed_len = if data.len() / num_values > 0 { data.len() / num_values } else { 0 };
            if fixed_len == 0 { return Ok(vec![ParquetValue::Null; num_values]); }
            let mut vals = Vec::new();
            for i in 0..num_values {
                let start = i * fixed_len;
                let end = start + fixed_len;
                if end <= data.len() {
                    vals.push(ParquetValue::FixedLenByteArray(data[start..end].to_vec()));
                }
            }
            Ok(vals)
        },
        "group" => Ok(vec![]),
        _ => Ok(vec![]),
    }
}

fn decode_byte_stream_split(data: &[u8], physical_type: &str, num_values: usize) -> Result<Vec<ParquetValue>, String> {
    match physical_type {
        "FLOAT" => {
            if data.len() < 4 * num_values { return Err("byte_stream_split float too short".to_string()); }
            let mut out = Vec::with_capacity(num_values);
            for i in 0..num_values {
                let b0 = data[i];
                let b1 = data[num_values + i];
                let b2 = data[2*num_values + i];
                let b3 = data[3*num_values + i];
                let f = f32::from_le_bytes([b0,b1,b2,b3]);
                out.push(ParquetValue::Float(f));
            }
            Ok(out)
        },
        "DOUBLE" => {
            if data.len() < 8 * num_values { return Err("byte_stream_split double too short".to_string()); }
            let mut out = Vec::with_capacity(num_values);
            for i in 0..num_values {
                let b0 = data[i];
                let b1 = data[num_values + i];
                let b2 = data[2*num_values + i];
                let b3 = data[3*num_values + i];
                let b4 = data[4*num_values + i];
                let b5 = data[5*num_values + i];
                let b6 = data[6*num_values + i];
                let b7 = data[7*num_values + i];
                let d = f64::from_le_bytes([b0,b1,b2,b3,b4,b5,b6,b7]);
                out.push(ParquetValue::Double(d));
            }
            Ok(out)
        },
        _ => Err("byte_stream_split unsupported".to_string()),
    }
}

fn decode_delta_binary_packed(data: &[u8], physical_type: &str) -> Result<Vec<ParquetValue>, String> {
    struct BitReader<'a> { data: &'a [u8], pos: usize, bit_pos: usize, }
    impl<'a> BitReader<'a> {
        fn new(data: &'a [u8], start: usize) -> Self { Self { data, pos: start, bit_pos: 0 } }
        fn read_bits(&mut self, n: usize) -> u64 {
            let mut result = 0u64;
            let mut bits_read = 0;
            while bits_read < n {
                if self.pos >= self.data.len() { break; }
                let remaining_bits = 8 - self.bit_pos;
                let bits_to_read = (n - bits_read).min(remaining_bits);
                let mask = ((1u64 << bits_to_read) - 1) << self.bit_pos;
                let byte = self.data[self.pos] as u64;
                let bits = (byte & mask) >> self.bit_pos;
                result |= bits << bits_read;
                bits_read += bits_to_read;
                self.bit_pos += bits_to_read;
                if self.bit_pos >= 8 { self.pos += 1; self.bit_pos = 0; }
            }
            result
        }
    }

    fn read_varint(data: &[u8], mut pos: usize) -> (u64, usize) {
        let mut res = 0u64;
        let mut shift = 0;
        while pos < data.len() {
            let b = data[pos];
            pos += 1;
            res |= ((b & 0x7f) as u64) << shift;
            if (b & 0x80) == 0 { break; }
            shift += 7;
        }
        (res, pos)
    }
    fn zigzag_to_i64(n: u64) -> i64 { ((n>>1) as i64) ^ -((n&1) as i64) }

    let mut pos = 0;
    if data.is_empty() { return Ok(vec![]); }

    let (block_size, p) = read_varint(data, pos);
    pos = p;
    let (num_mini_blocks, p) = read_varint(data, pos);
    pos = p;
    let (num_values, p) = read_varint(data, pos);
    pos = p;
    let (first_value_zigzag, p) = read_varint(data, pos);
    pos = p;
    let mut first_value = zigzag_to_i64(first_value_zigzag);

    let mut values = Vec::new();
    if physical_type == "INT32" {
        values.push(ParquetValue::Int32(first_value as i32));
    } else if physical_type == "INT64" {
        values.push(ParquetValue::Int64(first_value));
    } else {
        return Err("delta binary packed only for int".to_string());
    }

    while values.len() < num_values as usize && pos < data.len() {
        let (min_delta_zigzag, p) = read_varint(data, pos);
        pos = p;
        let min_delta = zigzag_to_i64(min_delta_zigzag);

        let mut bit_widths = Vec::new();
        for _ in 0..num_mini_blocks {
            if pos >= data.len() { break; }
            bit_widths.push(data[pos]);
            pos += 1;
        }

        for &bw in &bit_widths {
            if values.len() >= num_values as usize { break; }
            if bw == 0 {
                let count = std::cmp::min(block_size as usize, num_values as usize - values.len());
                for _ in 0..count {
                    if values.len() >= num_values as usize { break; }
                    first_value += min_delta;
                    if physical_type == "INT32" { values.push(ParquetValue::Int32(first_value as i32)); } else { values.push(ParquetValue::Int64(first_value)); }
                }
            } else {
                let values_per_mini = (block_size / num_mini_blocks) as usize;
                let mut reader = BitReader::new(data, pos);
                for _ in 0..values_per_mini {
                    if values.len() >= num_values as usize { break; }
                    let delta = reader.read_bits(bw as usize) as i64;
                    let actual_delta = min_delta + delta;
                    first_value += actual_delta;
                    if physical_type == "INT32" { values.push(ParquetValue::Int32(first_value as i32)); } else { values.push(ParquetValue::Int64(first_value)); }
                }
                let bytes_consumed = (values_per_mini * bw as usize + 7)/8;
                pos += bytes_consumed;
            }
        }
    }

    Ok(values)
}
