fn collect_leaf_descendants(tree: &[SchemaNode], idx: usize) -> Vec<usize> {
    let mut leaves = Vec::new();
    let mut stack = vec![idx];
    while let Some(cur) = stack.pop() {
        if cur >= tree.len() { continue; }
        let node = &tree[cur];
        if node.is_leaf {
            // If cur == idx and it's leaf, that's the leaf itself, but we are called for group idx, so we should not include group itself, only its descendants
            if cur != idx {
                leaves.push(cur);
            } else {
                // If group called is leaf (should not happen in this branch), include it
                leaves.push(cur);
            }
        } else {
            for &child in node.children.iter().rev() {
                stack.push(child);
            }
        }
    }
    leaves
}

