                    decoded_idx += 1;
                } else {
                    result.push(ParquetValue::Null);
                }
            } else if def == max_def as i64 - 1 {
                result.push(ParquetValue::Null);
            } else {
                result.push(ParquetValue::Null);
            }
        }
    }

    Ok((rep_levels, def_levels, result))
}

