#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Compression {
    Uncompressed = 0,
    Snappy = 1,
    Gzip = 2,
    Lzo = 3,
    Brotli = 4,
    Lz4 = 5,
    Zstd = 6,
    Lz4Raw = 7,
}

impl From<i32> for Compression {
    fn from(v: i32) -> Self {
        match v {
            0 => Compression::Uncompressed,
            1 => Compression::Snappy,
            2 => Compression::Gzip,
            3 => Compression::Lzo,
            4 => Compression::Brotli,
            5 => Compression::Lz4,
            6 => Compression::Zstd,
            7 => Compression::Lz4Raw,
            _ => Compression::Uncompressed,
        }
    }
}

pub fn decompress(compression: Compression, input: &[u8], _uncompressed_size: usize) -> Result<Vec<u8>, String> {
    match compression {
        Compression::Uncompressed => Ok(input.to_vec()),
        Compression::Snappy => decompress_snappy(input),
        Compression::Gzip => {
            Err("GZIP decompression not implemented yet".to_string())
        },
        Compression::Zstd => decompress_zstd_lib(input),
        Compression::Lz4 | Compression::Lz4Raw => decompress_lz4_lib(input),
        _ => Err(format!("Compression {:?} not supported", compression)),
    }
}

fn decompress_snappy(input: &[u8]) -> Result<Vec<u8>, String> {
    fn read_varint(buf: &[u8]) -> Option<(usize, usize)> {
        let mut result: usize = 0;
        let mut shift = 0;
        let mut pos = 0;
        for _ in 0..10 {
            if pos >= buf.len() { return None; }
            let b = buf[pos];
            pos += 1;
            result |= ((b & 0x7f) as usize) << shift;
            if (b & 0x80) == 0 { return Some((result, pos)); }
            shift += 7;
        }
        None
    }

    let (uncompressed_len, header_len) = match read_varint(input) {
        Some(v) => v,
        None => (0, 0),
    };

    let compressed_data = if header_len > 0 && header_len < 10 {
        &input[header_len..]
    } else {
        input
    };

    decompress_snappy_raw(compressed_data, uncompressed_len)
}

fn decompress_snappy_raw(input: &[u8], _expected_len: usize) -> Result<Vec<u8>, String> {
    let mut output = Vec::with_capacity(1024);
    let mut pos = 0;
    while pos < input.len() {
        let tag = input[pos];
        pos += 1;
        let tag_type = tag & 0x03;
        if tag_type == 0 {
            let mut len = (tag >> 2) as usize;
            if len < 60 {
                len += 1;
            } else {
                let extra = (len - 60 + 1) as usize;
                if pos + extra > input.len() { return Err("snappy literal length overflow".to_string()); }
                let mut l = 0usize;
                for i in 0..extra {
                    l |= (input[pos + i] as usize) << (8 * i);
                }
                pos += extra;
                len = l + 1;
            }
            if pos + len > input.len() {
                return Err(format!("snappy literal data overflow: pos {} len {} input len {}", pos, len, input.len()));
            }
            output.extend_from_slice(&input[pos..pos+len]);
            pos += len;
        } else {
            let (copy_len, offset) = match tag_type {
                1 => {
                    let len = ((tag >> 2) & 0x07) as usize + 4;
                    if pos >= input.len() { return Err("snappy copy 1-byte offset missing".to_string()); }
                    let offset = (((tag as usize) >> 5) << 8) | (input[pos] as usize);
                    pos += 1;
                    (len, offset)
                },
                2 => {
                    let len = ((tag >> 2) as usize) + 4;
                    if pos + 2 > input.len() { return Err("snappy copy 2-byte offset missing".to_string()); }
                    let offset = (input[pos] as usize) | ((input[pos+1] as usize) << 8);
                    pos += 2;
                    (len, offset)
                },
                3 => {
                    let len = ((tag >> 2) as usize) + 4;
                    if pos + 4 > input.len() { return Err("snappy copy 4-byte offset missing".to_string()); }
                    let offset = (input[pos] as usize) | ((input[pos+1] as usize) << 8) | ((input[pos+2] as usize) << 16) | ((input[pos+3] as usize) << 24);
                    pos += 4;
                    (len, offset)
                },
                _ => unreachable!(),
            };
            if offset == 0 || offset > output.len() {
                return Err(format!("snappy invalid offset {} output len {}", offset, output.len()));
            }
            let start = output.len() - offset;
            for i in 0..copy_len {
                let b = output[start + i];
                output.push(b);
            }
        }
    }
    Ok(output)
}

fn decompress_zstd_lib(input: &[u8]) -> Result<Vec<u8>, String> {
    // Load libzstd.so.1 via dlopen and call ZSTD_decompress
    use std::ffi::CString;
    use std::os::raw::{c_void, c_char};

    #[allow(dead_code)]
    const RTLD_NOW: i32 = 2;

    extern "C" {
        fn dlopen(filename: *const c_char, flag: i32) -> *mut c_void;
        fn dlsym(handle: *mut c_void, symbol: *const c_char) -> *mut c_void;
        // fn dlclose(handle: *mut c_void) -> i32;
    }

    unsafe {
        let lib_name = CString::new("/lib/x86_64-linux-gnu/libzstd.so.1").unwrap();
        let handle = dlopen(lib_name.as_ptr(), RTLD_NOW);
        if handle.is_null() {
            return Err("dlopen libzstd failed".to_string());
        }

        let sym_decompress = CString::new("ZSTD_decompress").unwrap();
        let fn_ptr = dlsym(handle, sym_decompress.as_ptr());
        if fn_ptr.is_null() {
            return Err("dlsym ZSTD_decompress failed".to_string());
        }

        let sym_is_error = CString::new("ZSTD_isError").unwrap();
        let fn_is_error_ptr = dlsym(handle, sym_is_error.as_ptr());
        if fn_is_error_ptr.is_null() {
            return Err("dlsym ZSTD_isError failed".to_string());
        }

        let sym_get_frame_content_size = CString::new("ZSTD_getFrameContentSize").unwrap();
        let fn_get_size_ptr = dlsym(handle, sym_get_frame_content_size.as_ptr());

        // Determine output size: try to get frame content size
        let mut output_size = 0usize;
        if !fn_get_size_ptr.is_null() {
            type GetSizeFn = unsafe extern "C" fn(*const u8, usize) -> u64;
            let get_size: GetSizeFn = std::mem::transmute(fn_get_size_ptr);
            let size = get_size(input.as_ptr(), input.len());
            // ZSTD_CONTENTSIZE_ERROR and UNKNOWN are large values, check if plausible
            if size != 0 && size != u64::MAX && size < 100_000_000 {
                output_size = size as usize;
            }
        }

        if output_size == 0 {
            output_size = input.len() * 10 + 1024;
            if output_size < 1024*1024 {
                output_size = 1024*1024;
            }
        }

        let mut output = vec![0u8; output_size];

        type DecompressFn = unsafe extern "C" fn(*mut u8, usize, *const u8, usize) -> usize;
        let decompress_fn: DecompressFn = std::mem::transmute(fn_ptr);

        let ret = decompress_fn(output.as_mut_ptr(), output.len(), input.as_ptr(), input.len());

        type IsErrorFn = unsafe extern "C" fn(usize) -> u32;
        let is_error_fn: IsErrorFn = std::mem::transmute(fn_is_error_ptr);

        if is_error_fn(ret) != 0 {
            return Err(format!("ZSTD decompress error code {}", ret));
        }

        output.truncate(ret);
        Ok(output)
    }
}

fn decompress_lz4_lib(input: &[u8]) -> Result<Vec<u8>, String> {
    use std::ffi::CString;
    use std::os::raw::{c_void, c_char};

    const RTLD_NOW: i32 = 2;

    extern "C" {
        fn dlopen(filename: *const c_char, flag: i32) -> *mut c_void;
        fn dlsym(handle: *mut c_void, symbol: *const c_char) -> *mut c_void;
    }

    unsafe {
        let lib_name = CString::new("/lib/x86_64-linux-gnu/liblz4.so.1").unwrap();
        let handle = dlopen(lib_name.as_ptr(), RTLD_NOW);
        if handle.is_null() {
            return Err("dlopen liblz4 failed".to_string());
        }

        let sym = CString::new("LZ4_decompress_safe").unwrap();
        let fn_ptr = dlsym(handle, sym.as_ptr());
        if fn_ptr.is_null() {
            return Err("dlsym LZ4_decompress_safe failed".to_string());
        }

        // Guess output size as input*10 or 1M
        let output_size = input.len() * 10 + 1024;
        let mut output = vec![0u8; output_size];

        type Lz4Fn = unsafe extern "C" fn(*const u8, *mut u8, i32, i32) -> i32;
        let lz4_fn: Lz4Fn = std::mem::transmute(fn_ptr);

        let ret = lz4_fn(input.as_ptr(), output.as_mut_ptr(), input.len() as i32, output.len() as i32);
        if ret < 0 {
            return Err(format!("LZ4 decompress error {}", ret));
        }
        output.truncate(ret as usize);
        Ok(output)
    }
}
