fn decode_delta_length_byte_array(data: &[u8], num_values: usize) -> Result<Vec<ParquetValue>, String> {
    // First decode lengths via delta binary packed
    // The data starts with delta binary packed for lengths
    // We need to parse varints to know where lengths section ends and data begins
    // The delta binary packed decoder returns values, but we need to know how many bytes it consumed.
    // For simplicity, we will attempt to decode lengths and then use remaining bytes

    // Use helper to decode delta binary packed and also return consumed bytes
    fn read_varint(data: &[u8], mut pos: usize) -> (u64, usize) {
        let mut res = 0u64;
        let mut shift = 0;
        while pos < data.len() {
            let b = data[pos];
            pos += 1;
            res |= ((b & 0x7f) as u64) << shift;
            if (b & 0x80) == 0 { break; }
            shift += 7;
        }
        (res, pos)
    }
    fn zigzag_to_i64(n: u64) -> i64 { ((n>>1) as i64) ^ -((n&1) as i64) }

    // Decode delta binary packed for lengths
    // We will parse manually similar to decode_delta_binary_packed but for i32 lengths

    let mut pos = 0;
    if data.is_empty() { return Ok(vec![]); }

    let (block_size, p) = read_varint(data, pos);
    pos = p;
    let (num_mini_blocks, p) = read_varint(data, pos);
    pos = p;
    let (num_values, p) = read_varint(data, pos);
    pos = p;
    let (first_value_zigzag, p) = read_varint(data, pos);
    pos = p;
    let mut first_value = zigzag_to_i64(first_value_zigzag) as i32;

    let mut lengths: Vec<i32> = Vec::new();
    lengths.push(first_value);

    struct BitReader<'a> { data: &'a [u8], pos: usize, bit_pos: usize, }
    impl<'a> BitReader<'a> {
        fn new(data: &'a [u8], start: usize) -> Self { Self { data, pos: start, bit_pos: 0 } }
        fn read_bits(&mut self, n: usize) -> u64 {
            let mut result = 0u64;
            let mut bits_read = 0;
            while bits_read < n {
                if self.pos >= self.data.len() { break; }
                let remaining_bits = 8 - self.bit_pos;
                let bits_to_read = (n - bits_read).min(remaining_bits);
                let mask = ((1u64 << bits_to_read) - 1) << self.bit_pos;
                let byte = self.data[self.pos] as u64;
                let bits = (byte & mask) >> self.bit_pos;
                result |= bits << bits_read;
                bits_read += bits_to_read;
                self.bit_pos += bits_to_read;
                if self.bit_pos >= 8 { self.pos += 1; self.bit_pos = 0; }
            }
            result
        }
    }

    while lengths.len() < num_values as usize && pos < data.len() {
        let (min_delta_zigzag, p) = read_varint(data, pos);
        pos = p;
        let min_delta = zigzag_to_i64(min_delta_zigzag) as i32;
        let mut bit_widths = Vec::new();
        for _ in 0..num_mini_blocks {
            if pos >= data.len() { break; }
            bit_widths.push(data[pos]);
            pos += 1;
        }
        for &bw in &bit_widths {
            if lengths.len() >= num_values as usize { break; }
            if bw == 0 {
                let count = std::cmp::min(block_size as usize, num_values as usize - lengths.len());
                for _ in 0..count {
                    if lengths.len() >= num_values as usize { break; }
                    first_value += min_delta;
                    lengths.push(first_value);
                }
            } else {
                let values_per_mini = (block_size / num_mini_blocks) as usize;
                let mut reader = BitReader::new(data, pos);
                for _ in 0..values_per_mini {
                    if lengths.len() >= num_values as usize { break; }
                    let delta = reader.read_bits(bw as usize) as i32;
                    let actual_delta = min_delta + delta;
                    first_value += actual_delta;
                    lengths.push(first_value);
                }
                let bytes_consumed = (values_per_mini * bw as usize + 7)/8;
                pos += bytes_consumed;
            }
        }
    }

    // Now pos is at start of concatenated byte array data
    let mut out: Vec<ParquetValue> = Vec::new();
    let mut data_pos = pos;
    for &len in &lengths {
        if data_pos + len as usize > data.len() { break; }
        let b = data[data_pos..data_pos+len as usize].to_vec();
        data_pos += len as usize;
        out.push(ParquetValue::ByteArray(b));
        if out.len() >= num_values { break; }
    }

    Ok(out)
}

