                        let delta = reader.read_bits(bw as usize) as i32;
                        let actual_delta = min_delta + delta;
                        first_value += actual_delta;
                        lengths.push(first_value);
                    }
                    let bytes_consumed = (values_per_mini * bw as usize + 7)/8;
                    pos += bytes_consumed;
                }
            }
        }
        (lengths, pos)
    }

    let (prefix_lengths, pos1) = decode_lengths(data, 0);
    let (suffix_lengths, pos2) = decode_lengths(data, pos1);

    // Now remaining data is suffixes
    let mut out: Vec<ParquetValue> = Vec::new();
    let mut data_pos = pos2;
    let mut prev = Vec::new();

    for i in 0..num_values {
        if i >= prefix_lengths.len() || i >= suffix_lengths.len() { break; }
        let prefix_len = prefix_lengths[i] as usize;
        let suffix_len = suffix_lengths[i] as usize;
        if data_pos + suffix_len > data.len() { break; }
        let suffix = &data[data_pos..data_pos+suffix_len];
        data_pos += suffix_len;
        let mut full = Vec::new();
        if prefix_len > 0 && prefix_len <= prev.len() {
            full.extend_from_slice(&prev[..prefix_len]);
        }
        full.extend_from_slice(suffix);
        out.push(ParquetValue::ByteArray(full.clone()));
        prev = full;
