        if ftype in (4,5,6):
            v,p=read_varint(buf,p)  # simplified zigzag? Actually read zigzag
            # For quick, read varint as zigzag?
            # We'll use zigzag conversion
            def zigzag(n):
                return (n>>1) ^ -(n&1)
            v=zigzag(v)
            hdr[last_id]=v
        elif ftype==8:
            l,p=read_varint(buf,p)
            v=buf[p:p+l]; p+=l
            hdr[last_id]=v
        elif ftype==12:
            p=skip_struct(buf,p)
            hdr[last_id]="struct"
        elif ftype==9:
            b2=buf[p]; p+=1
            et=b2&0x0f
            szn=(b2>>4)&0x0f
            if szn==15:
                sz,p=read_varint(buf,p)
            else:
                sz=szn
            for _ in range(sz):
                if et==12:
                    p=skip_struct(buf,p)
                elif et in (4,5,6):
                    _,p=read_varint(buf,p)
                elif et==8:
                    ll,p=read_varint(buf,p)
                    p+=ll
                elif et==3:
                    p+=1
            hdr[last_id]=f"list"
        elif ftype in (1,2):
            hdr[last_id]=(ftype==1)
        elif ftype==3:
            hdr[last_id]=buf[p]; p+=1
        elif ftype==7:
            p+=8
    return hdr,p

